export interface ActivityClock {
  month: number;
  day: number;
  hour: number;
  minute: number;
}

export interface ActivitySession {
  id: string;
  title: string;
  time: string;
  content: string;
}

export interface ActivityForm {
  name: string;
  location: string;
  month: number;
  time: string;
  sessions: ActivitySession[];
}

export interface ActivityArchive {
  id: string;
  name: string;
  content: string;
  custom?: boolean;
  displayName: string;
  location: string;
  month: number;
  time: string;
  days: number[];
}

const CUSTOM_ACTIVITY_KEY = 'campus-app-custom-activities';

function getStorage(): Storage | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

function createId(prefix: string): string {
  return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;
}

export function createActivitySession(title = '', time = '', content = ''): ActivitySession {
  return {
    id: createId('session'),
    title,
    time,
    content,
  };
}

export function clampMonth(value: number): number {
  if (!Number.isFinite(value)) return 9;
  return Math.min(12, Math.max(1, Math.round(value)));
}

export function daysInMonth(year: number, month: number): number {
  return new Date(year, clampMonth(month), 0).getDate();
}

export function clampDay(year: number, month: number, day: number): number {
  const last = daysInMonth(year, month);
  if (!Number.isFinite(day)) return 1;
  return Math.min(last, Math.max(1, Math.round(day)));
}

export function weekdayIndex(year: number, month: number, day: number): number {
  const jsDay = new Date(year, clampMonth(month) - 1, day).getDay();
  return jsDay === 0 ? 7 : jsDay;
}

export function weekdayLabel(year: number, month: number, day: number): string {
  return `星期${['一', '二', '三', '四', '五', '六', '日'][weekdayIndex(year, month, day) - 1]}`;
}

function pad2(value: number): string {
  return String(Math.max(0, Math.round(value))).padStart(2, '0');
}

export function clampHour(value: number): number {
  if (!Number.isFinite(value)) return 0;
  return Math.min(23, Math.max(0, Math.round(value)));
}

export function clampMinute(value: number): number {
  if (!Number.isFinite(value)) return 0;
  return Math.min(59, Math.max(0, Math.round(value)));
}

export function normalizeClock(clock: ActivityClock, year = 2025): ActivityClock {
  const month = clampMonth(clock.month);
  return {
    month,
    day: clampDay(year, month, clock.day),
    hour: clampHour(clock.hour),
    minute: clampMinute(clock.minute),
  };
}

export function formatClock(clock: ActivityClock, year = 2025): string {
  const next = normalizeClock(clock, year);
  return `${next.month}月${next.day}日 ${pad2(next.hour)}:${pad2(next.minute)}`;
}

export function formatTimeRange(start: ActivityClock, end: ActivityClock, year = 2025): string {
  return `${formatClock(start, year)}-${formatClock(end, year)}`;
}

export function parseTimeRange(text: string, fallbackMonth = 9): { start: ActivityClock; end: ActivityClock } {
  const dated: ActivityClock[] = [];
  const datedRe = /(\d{1,2})\s*月\s*(\d{1,2})\s*日(?:\s*(\d{1,2})\s*[:：时]\s*(\d{1,2})\s*分?)?/g;
  for (const match of String(text || '').matchAll(datedRe)) {
    dated.push({
      month: clampMonth(Number(match[1])),
      day: Number(match[2]),
      hour: match[3] != null ? clampHour(Number(match[3])) : 0,
      minute: match[4] != null ? clampMinute(Number(match[4])) : 0,
    });
  }

  if (dated.length >= 2) {
    return { start: dated[0], end: dated[dated.length - 1] };
  }

  if (dated.length === 1) {
    const times = [...String(text || '').matchAll(/(\d{1,2})\s*[:：]\s*(\d{1,2})/g)];
    if (times.length >= 2) {
      return {
        start: { ...dated[0], hour: clampHour(Number(times[0][1])), minute: clampMinute(Number(times[0][2])) },
        end: { ...dated[0], hour: clampHour(Number(times[times.length - 1][1])), minute: clampMinute(Number(times[times.length - 1][2])) },
      };
    }
    return { start: dated[0], end: dated[0] };
  }

  const month = clampMonth(fallbackMonth);
  return {
    start: { month, day: 1, hour: 8, minute: 0 },
    end: { month, day: 1, hour: 18, minute: 0 },
  };
}

function daysBetween(start: ActivityClock, end: ActivityClock, year: number, month: number): number[] {
  const from = new Date(year, clampMonth(start.month) - 1, Math.max(1, start.day));
  const to = new Date(year, clampMonth(end.month) - 1, Math.max(1, end.day));
  const first = from <= to ? from : to;
  const last = from <= to ? to : from;
  const days: number[] = [];
  const cursor = new Date(first);
  while (cursor <= last) {
    if (cursor.getMonth() + 1 === month) days.push(cursor.getDate());
    cursor.setDate(cursor.getDate() + 1);
  }
  return days;
}

export function emptyActivityForm(name = '', month = 9, day = 1): ActivityForm {
  const start = normalizeClock({ month, day, hour: 8, minute: 0 });
  const end = normalizeClock({ month, day, hour: 18, minute: 0 });
  const time = formatTimeRange(start, end);
  return {
    name,
    location: '',
    month: start.month,
    time,
    sessions: [createActivitySession('', time)],
  };
}

function fieldValue(content: string, label: string): string {
  const escaped = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const match = content.match(new RegExp(`^\\s*${escaped}[：:]\\s*(.*)$`, 'm'));
  return match?.[1].trim() || '';
}

export function parseActivityMonth(content: string, fallback = 9): number {
  const explicit = Number(fieldValue(content, '活动月份').replace(/[^\d]/g, ''));
  if (explicit >= 1 && explicit <= 12) return explicit;
  const time = fieldValue(content, '活动时间');
  const match = time.match(/(\d{1,2})\s*月/);
  if (match) return clampMonth(Number(match[1]));
  return clampMonth(fallback);
}

function uniqueDays(days: number[]): number[] {
  return [...new Set(days.filter(day => Number.isFinite(day) && day >= 1))].sort((a, b) => a - b);
}

export function parseActivityDays(time: string, year: number, month: number): number[] {
  const range = parseTimeRange(time, month);
  return uniqueDays(daysBetween(range.start, range.end, year, month));
}

export function collectActivityDays(form: ActivityForm, year: number, month: number): number[] {
  return uniqueDays([
    ...parseActivityDays(form.time, year, month),
    ...form.sessions.flatMap(session => parseActivityDays(session.time, year, month)),
  ]);
}

export function parseActivityForm(content: string, fallbackName = ''): ActivityForm {
  const sessions: ActivitySession[] = [];
  const lines = content.replace(/\r\n/g, '\n').split('\n');
  for (let index = 0; index < lines.length; index += 1) {
    const match = lines[index].match(/^\s*环节\d+[：:]\s*(.*)$/);
    if (!match) continue;
    const title = match[1].trim();
    let time = '';
    const contentLines: string[] = [];
    let cursor = index + 1;
    while (cursor < lines.length) {
      const line = lines[cursor];
      if (/^\s*环节\d+[：:]/.test(line) || /^\s*<\/activity_/.test(line)) break;
      const timeMatch = line.match(/^\s*时间[：:]\s*(.*)$/);
      if (timeMatch) {
        time = timeMatch[1].trim();
        cursor += 1;
        continue;
      }
      const contentMatch = line.match(/^\s*内容[：:]\s*(.*)$/);
      if (contentMatch) {
        if (contentMatch[1].trim()) contentLines.push(contentMatch[1].trim());
        cursor += 1;
        while (cursor < lines.length) {
          const next = lines[cursor];
          if (/^\s*环节\d+[：:]/.test(next) || /^\s*<\/activity_/.test(next) || /^\s*时间[：:]/.test(next)) break;
          if (next.trim()) contentLines.push(next.trim());
          cursor += 1;
        }
        continue;
      }
      cursor += 1;
    }
    sessions.push(createActivitySession(title, time, contentLines.join('\n')));
    index = cursor - 1;
  }

  const rawTime = fieldValue(content, '活动时间');
  const rawMonth = parseActivityMonth(content);
  const range = parseTimeRange(rawTime, rawMonth);
  const normalizedSessions = (sessions.length ? sessions : [createActivitySession()]).map(session => {
    const sessionRange = parseTimeRange(session.time || rawTime, range.start.month);
    return { ...session, time: formatTimeRange(sessionRange.start, sessionRange.end) };
  });

  return {
    name: fieldValue(content, '活动名称') || fallbackName,
    location: fieldValue(content, '活动地点'),
    month: range.start.month,
    time: formatTimeRange(range.start, range.end),
    sessions: normalizedSessions,
  };
}

export function serializeActivityForm(form: ActivityForm): string {
  const name = form.name.trim() || '未命名活动';
  const range = parseTimeRange(form.time, form.month);
  const time = formatTimeRange(range.start, range.end);
  const month = range.start.month;
  const sessions = form.sessions.filter(
    session => session.title.trim() || session.time.trim() || session.content.trim(),
  );
  const sessionLines = sessions.flatMap((session, index) => {
    const sessionRange = parseTimeRange(session.time || time, month);
    const content = session.content.replace(/\r\n/g, '\n').trim();
    const [first, ...rest] = content ? content.split('\n') : [''];
    return [
      `环节${index + 1}: ${session.title.trim() || `环节${index + 1}`}`,
      `时间: ${formatTimeRange(sessionRange.start, sessionRange.end)}`,
      `内容: ${first}`,
      ...rest,
      '',
    ];
  });

  return [
    `<activity_${name}>`,
    '',
    `活动名称: ${name}`,
    `活动地点: ${form.location.trim()}`,
    `活动月份: ${month}月`,
    `活动时间: ${time}`,
    '',
    '【活动环节】',
    ...sessionLines,
    `</activity_${name}>`,
  ].join('\n');
}

function builtinActivity(
  id: string,
  name: string,
  location: string,
  month: number,
  time: string,
  sessions: Array<[string, string, string]>,
): ActivityArchive {
  const form: ActivityForm = {
    name,
    location,
    month,
    time,
    sessions: sessions.map(([title, sessionTime, content]) => createActivitySession(title, sessionTime, content)),
  };
  return parseActivityArchive(id, serializeActivityForm(form), false);
}

