export const DEFAULT_ACTIVITY_IDS = DEFAULT_ACTIVITIES.map(item => item.id);

export function parseActivityArchive(id: string, content: string, custom = false, year = 2025): ActivityArchive {
  const form = parseActivityForm(content, id);
  return {
    id,
    name: id,
    content,
    custom,
    displayName: form.name || id,
    location: form.location || '未知地点',
    month: form.month,
    time: form.time || `${form.month}月`,
    days: collectActivityDays(form, year, form.month),
  };
}

function loadCustomActivityRecords(): { id: string; content: string }[] {
  const storage = getStorage();
  if (!storage) return [];
  try {
    const parsed = JSON.parse(storage.getItem(CUSTOM_ACTIVITY_KEY) || '[]') as { id?: string; name?: string; content?: string }[];
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter(item => item && String(item.content || '').trim())
      .map(item => ({
        id: String(item.id || item.name || '').trim(),
        content: String(item.content || ''),
      }))
      .filter(item => item.id);
  } catch {
    return [];
  }
}

function saveCustomActivityRecords(records: { id: string; content: string }[]) {
  const storage = getStorage();
  if (!storage) return;
  try {
    storage.setItem(CUSTOM_ACTIVITY_KEY, JSON.stringify(records));
  } catch {
    // ignore quota / private mode
  }
}

export function loadCustomActivities(year = 2025): ActivityArchive[] {
  return loadCustomActivityRecords().map(item => parseActivityArchive(item.id, item.content, true, year));
}

export function loadAllActivities(year = 2025): ActivityArchive[] {
  const custom = loadCustomActivities(year);
  const used = new Set(DEFAULT_ACTIVITIES.map(item => item.id));
  return [
    ...DEFAULT_ACTIVITIES.map(item => parseActivityArchive(item.id, item.content, false, year)),
    ...custom.filter(item => {
      if (used.has(item.id)) return false;
      used.add(item.id);
      return true;
    }),
  ];
}

export function getActivityById(id: string): ActivityArchive | undefined {
  return loadAllActivities().find(item => item.id === id);
}

export function addCustomActivity(form: ActivityForm): ActivityArchive {
  const name = form.name.trim() || '未命名活动';
  const id = `custom-activity-${Date.now().toString(36)}`;
  const content = serializeActivityForm({ ...form, name });
  saveCustomActivityRecords([...loadCustomActivityRecords(), { id, content }]);
  return parseActivityArchive(id, content, true);
}

export function upsertCustomActivity(id: string, content: string): ActivityArchive {
  const records = loadCustomActivityRecords();
  const next = { id, content };
  const index = records.findIndex(item => item.id === id);
  if (index >= 0) records[index] = next;
  else records.push(next);
  saveCustomActivityRecords(records);
  return parseActivityArchive(id, content, true);
}

export function deleteCustomActivity(id: string): boolean {
  const current = loadCustomActivityRecords();
  const next = current.filter(item => item.id !== id);
  if (next.length === current.length) return false;
  saveCustomActivityRecords(next);
  return true;
}

export function buildCalendarCells(year: number, month: number): Array<{ day: number | null; weekday: number }> {
  const firstWeekday = weekdayIndex(year, month, 1);
  const last = daysInMonth(year, month);
  const leading = firstWeekday - 1;
  const cells: Array<{ day: number | null; weekday: number }> = [];
  for (let index = 0; index < leading; index += 1) {
    cells.push({ day: null, weekday: ((firstWeekday - leading + index - 1 + 7) % 7) + 1 });
  }
  for (let day = 1; day <= last; day += 1) {
    cells.push({ day, weekday: weekdayIndex(year, month, day) });
  }
  while (cells.length % 7 !== 0) {
    cells.push({ day: null, weekday: (cells.length % 7) + 1 });
  }
  return cells;
}
