import { AnimatePresence, motion } from 'framer-motion';
import { ChevronDown, Shirt } from 'lucide-react';
import React, { useEffect, useRef, useState } from 'react';
import { Player } from '../../types';
import { Card } from '../ui/Card';

interface ClothingInfoProps {
  clothing: Player['clothing'];
}

const ClothingItem: React.FC<{ label: string; value: string }> = ({ label, value }) => {
  const textRef = useRef<HTMLParagraphElement>(null);
  const [expanded, setExpanded] = useState(false);
  const [overflowing, setOverflowing] = useState(false);
  const text = value?.trim() || '未填写';

  useEffect(() => {
    const el = textRef.current;
    if (!el || expanded) return;

    const measure = () => {
      setOverflowing(el.scrollHeight - el.clientHeight > 1);
    };

    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, [text, expanded]);

  return (
    <div className="bg-surface rounded-xl p-3 border border-border-default shadow-sm flex items-start gap-2">
      <div className="min-w-0 flex-1 flex flex-col gap-1">
        <span className="text-[10px] font-bold text-text-secondary uppercase tracking-wider">{label}</span>
        <p
          ref={textRef}
          className={`text-xs text-text-primary font-medium leading-relaxed ${expanded ? 'whitespace-pre-wrap break-words' : 'line-clamp-2'}`}
        >
          {text}
        </p>
      </div>
      {(overflowing || expanded) && (
        <button
          type="button"
          onClick={() => setExpanded(prev => !prev)}
          className="shrink-0 p-1 rounded-full hover-fill text-text-secondary"
          aria-label={expanded ? '收起条目' : '展开条目'}
        >
          <ChevronDown className={`w-3.5 h-3.5 transition-transform ${expanded ? 'rotate-180' : ''}`} />
        </button>
      )}
    </div>
  );
};

export const ClothingInfo: React.FC<ClothingInfoProps> = ({ clothing }) => {
  const [open, setOpen] = useState(false);
  const clothingItems = [
    { label: '当前上装', val: clothing.upper },
    { label: '当前下装', val: clothing.lower },
    { label: '随身配饰', val: clothing.accessories },
    { label: '当前鞋履', val: clothing.shoes },
  ];

  return (
    <Card className="p-4">
      <button
        type="button"
        onClick={() => setOpen(prev => !prev)}
        className="w-full flex items-center justify-between gap-2"
      >
        <div className="flex items-center gap-1.5 text-sm font-bold text-text-primary">
          <Shirt className="w-4 h-4 text-sky-500" />
          衣着信息
        </div>
        <ChevronDown className={`w-4 h-4 text-text-secondary transition-transform ${open ? 'rotate-180' : ''}`} />
      </button>

      <AnimatePresence initial={false}>
        {open && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.22 }}
            className="overflow-hidden"
          >
            <div className="flex flex-col gap-2 mt-3">
              {clothingItems.map(item => (
                <ClothingItem key={item.label} label={item.label} value={item.val} />
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </Card>
  );
};
