import React from 'react';
import { Player, Character } from '../../types';
import { motion } from 'framer-motion';
import { useDraggableScroll } from '../../hooks/useDraggableScroll';
import { PlayerProfile } from './PlayerProfile';
import { ClothingInfo } from './ClothingInfo';
import { SecretCrush } from './SecretCrush';
import { FullScreenModal } from '../ui/Modal';
import { User, ChevronLeft } from 'lucide-react';

interface ProfileScreenProps {
  player: Player;
  setPlayer: React.Dispatch<React.SetStateAction<Player>>;
  characters: Character[];
  onCharacterClick: (char: Character) => void;
  onClose: () => void;
}

/**
 * 主界面 (HomeScreen)
 * 游戏的主要信息展示面板，包含了玩家个人信息、衣着信息以及"倾心于你"角色列表
 */
export function ProfileScreen({ player, setPlayer, characters, onCharacterClick, onClose }: ProfileScreenProps) {
  // 筛选出好感度达到 80 及以上的角色作为"倾心于你"列表
  const crushingCharacters = characters.filter(c => c.affinity >= 80);
  
  // 引入拖拽滚动 hook，使整个主界面可以通过拖拽进行滚动
  const dragProps = useDraggableScroll<HTMLDivElement>();

  // 处理玩家上传新头像的逻辑
  const handlePlayerAvatarUpload = (dataUrl: string) => {
    setPlayer(prev => ({ ...prev, avatar: dataUrl }));
  };

  return (
    <FullScreenModal isOpen={true} className="z-20">
      <div className="p-4 sticky top-0 z-10 border-b border-border-default/30">
        <div className="flex items-center justify-between mb-2">
          <h1 className="text-xl font-bold text-text-primary flex items-center gap-2">
            <User className="w-6 h-6 text-indigo-400" />
            个人信息
          </h1>
          <button onClick={onClose} className="p-2 glass rounded-full hover-fill transition-colors shadow-sm">
            <ChevronLeft className="w-5 h-5 text-text-primary" />
          </button>
        </div>
      </div>
      <div 
        className="flex flex-col p-5 min-h-0 flex-1 overflow-y-auto overflow-x-hidden hide-scrollbar pb-6"
        {...dragProps} ref={dragProps.ref}
      >
      {/* ================= 模块一：玩家信息 ================= */}
      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.1 }}
        className="mb-8"
      >
        <h2 className="text-xs uppercase tracking-widest text-text-secondary font-bold mb-4">
          玩家信息 / Player Profile
        </h2>
        
        {/* 1.1 个人信息模块：包含头像、名字、身份 */}
        <PlayerProfile player={player} onAvatarUpload={handlePlayerAvatarUpload} />
        
        {/* 1.2 衣着信息模块：包含上装、下装、配饰、鞋履 */}
        <ClothingInfo clothing={player.clothing} />
      </motion.div>

      {/* ================= 模块二：倾心于你 ================= */}
      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.2 }}
        className="flex flex-col"
      >
        <h2 className="text-xs uppercase tracking-widest text-text-secondary font-bold mb-4">
          倾心于你 / Secret Crush
        </h2>
        
        {/* 2.1 倾心于你列表模块：展示高好感度的角色 */}
        <SecretCrush crushingCharacters={crushingCharacters} onCharacterClick={onCharacterClick} />
      </motion.div>
      </div>
    </FullScreenModal>
  );
}
