import { useCallback, useEffect, useRef, useState } from 'react';
import { ChevronLeft, Hammer, Move, Pencil, Trash2 } from 'lucide-react';
import { BottomSheetModal, FullScreenModal } from '../状态栏/src/components/ui/Modal';
import { BUILDING_COLOR_PALETTES, BUILDING_COLORS, getBuildingTextColor } from '../状态栏/src/data';
import { useDraggableScroll } from '../状态栏/src/hooks/useDraggableScroll';
import { CampusBuilding } from '../状态栏/src/types';

const GRID_WIDTH = 32;
const GRID_HEIGHT = 31;
const CELL_SIZE = 60;
const GAP = 6;
const PADDING = 16;
const MAP_WIDTH = GRID_WIDTH * CELL_SIZE + (GRID_WIDTH - 1) * GAP + PADDING * 2;
const MAP_HEIGHT = GRID_HEIGHT * CELL_SIZE + (GRID_HEIGHT - 1) * GAP + PADDING * 2;
const ZOOM = 0.22;

type PlacingState = {
  mode: 'create' | 'move';
  building: {
    id?: string;
    name: string;
    width: number;
    height: number;
    color: string;
    description?: string;
    facilityType?: string;
  };
  previewX: number | null;
  previewY: number | null;
  originalBuilding?: CampusBuilding;
};

function cloneBuildings(buildings: CampusBuilding[]): CampusBuilding[] {
  return buildings.map(item => ({ ...item }));
}

export function CampusMapEditor({
  open,
  buildings,
  onClose,
  onSave,
}: {
  open: boolean;
  buildings: CampusBuilding[];
  onClose: () => void;
  onSave: (buildings: CampusBuilding[]) => void;
}) {
  const dragProps = useDraggableScroll<HTMLDivElement>();
  const buildScrollProps = useDraggableScroll<HTMLDivElement>();
  const editScrollProps = useDraggableScroll<HTMLDivElement>();
  const [draft, setDraft] = useState<CampusBuilding[]>(() => cloneBuildings(buildings));
  const [showBuildModal, setShowBuildModal] = useState(false);
  const [placingState, setPlacingState] = useState<PlacingState | null>(null);
  const [editingBuilding, setEditingBuilding] = useState<CampusBuilding | null>(null);
  const [buildForm, setBuildForm] = useState({
    name: '',
    width: 5,
    height: 3,
    color: BUILDING_COLORS[0],
    description: '',
    facilityType: BUILDING_COLOR_PALETTES[0].category,
  });
  const timerRef = useRef<number | null>(null);
  const wasLongPressed = useRef(false);

  // 仅在打开瞬间同步外部 buildings。
  // 打开后父组件重渲染常会给出新数组引用；若监听 buildings，编辑弹层会被反复冲掉。
  useEffect(() => {
    if (!open) {
      setPlacingState(null);
      setEditingBuilding(null);
      setShowBuildModal(false);
      return;
    }
    setDraft(cloneBuildings(buildings));
    setPlacingState(null);
    setEditingBuilding(null);
    setShowBuildModal(false);
  }, [open]);

  const centerMap = useCallback(() => {
    const container = dragProps.ref.current;
    if (!container) return;
    container.scrollTop = Math.max(0, (container.scrollHeight - container.clientHeight) / 2 + 2 * (CELL_SIZE + GAP) * ZOOM);
    container.scrollLeft = Math.max(0, (container.scrollWidth - container.clientWidth) / 2);
  }, [dragProps.ref]);

  useEffect(() => {
    if (!open) return;
    const timer = window.setTimeout(centerMap, 80);
    return () => window.clearTimeout(timer);
  }, [open, centerMap, draft.length]);

  const handleCellClick = (x: number, y: number) => {
    if (!placingState) return;
    let hitsWall = false;
    for (let i = x; i < x + placingState.building.width; i++) {
      for (let j = y; j < y + placingState.building.height; j++) {
        if (i <= 1 || i >= GRID_WIDTH - 2 || j <= 1 || j >= GRID_HEIGHT - 2) hitsWall = true;
      }
    }
    if (hitsWall) return;
    const isOverlap = draft.some(
      item =>
        item.id !== placingState.originalBuilding?.id &&
        x < item.x + item.width &&
        x + placingState.building.width > item.x &&
        y < item.y + item.height &&
        y + placingState.building.height > item.y,
    );
    if (isOverlap) return;
    setPlacingState(prev => (prev ? { ...prev, previewX: x, previewY: y } : null));
  };

  const confirmPlace = () => {
    if (!placingState || placingState.previewX == null || placingState.previewY == null) return;
    const palette = BUILDING_COLOR_PALETTES.find(item => item.colorClass === placingState.building.color);
    if (placingState.mode === 'create') {
      setDraft(prev => [
        ...prev,
        {
          id: `custom-building-${Date.now().toString(36)}`,
          name: placingState.building.name,
          x: placingState.previewX!,
          y: placingState.previewY!,
          width: placingState.building.width,
          height: placingState.building.height,
          color: placingState.building.color,
          description: placingState.building.description || '',
          facilityType: placingState.building.facilityType || palette?.category || '学习设施',
        },
      ]);
    } else if (placingState.originalBuilding) {
      setDraft(prev =>
        prev.map(item =>
          item.id === placingState.originalBuilding?.id
            ? { ...item, ...placingState.building, x: placingState.previewX!, y: placingState.previewY! }
            : item,
        ),
      );
    }
    setPlacingState(null);
  };

  const updateEditingBuilding = (patch: Partial<CampusBuilding>) => {
    setEditingBuilding(prev => {
      if (!prev) return prev;
      const next = { ...prev, ...patch };
      setDraft(items => items.map(item => (item.id === next.id ? next : item)));
      return next;
    });
  };

  const displayBuildings = draft.filter(
    item => !(placingState?.mode === 'move' && item.id === placingState.originalBuilding?.id),
  );

  return (
    <FullScreenModal isOpen={open} className="z-[95] bg-[#e2e8f0] flex flex-col p-0 select-none bottom-0">
      <div className="absolute top-0 left-0 w-full z-50 glass border-b border-border-default/30 flex justify-between items-center p-3 shadow-sm bg-white/85">
        <h2 className="text-base font-bold text-text-primary">配置校园地图</h2>
        <div className="flex items-center gap-2">
          <button type="button" onClick={() => setShowBuildModal(true)} className="p-2 glass rounded-full text-text-primary" title="新增建筑">
            <Hammer className="w-5 h-5" />
          </button>
          <button
            type="button"
            onClick={() => onSave(draft.filter(item => item.name.trim()))}
            className="px-3 h-8 rounded-full text-xs font-bold accent-btn"
          >
            保存地图
          </button>
          <button type="button" onClick={onClose} className="p-2 glass rounded-full text-text-primary" title="返回">
            <ChevronLeft className="w-5 h-5" />
          </button>
        </div>
      </div>

      {placingState && (
        <div className="absolute bottom-4 left-0 w-full px-6 z-50 flex justify-between pointer-events-none">
          <button type="button" onClick={() => setPlacingState(null)} className="pointer-events-auto w-28 py-3 bg-white text-text-primary rounded-full font-bold border border-border-default">
            取消
          </button>
          <button type="button" disabled={placingState.previewX == null} onClick={confirmPlace} className="pointer-events-auto w-28 py-3 accent-btn rounded-full font-bold disabled:opacity-50">
            确认放置
          </button>
        </div>
      )}

      {!placingState && (
        <p className="absolute top-14 left-3 right-3 z-40 text-[11px] text-text-secondary bg-white/80 rounded-xl px-3 py-2 border border-white/70">
          可拖动查看地图。点建筑可编辑；长按建筑可改位置；右上角锤子可新增建筑。修改会实时反映到地图。
        </p>
      )}

      <div className="absolute inset-0 w-full h-full overflow-auto hide-scrollbar pt-24 pb-4" {...dragProps} ref={dragProps.ref}>
        <div className="w-max h-max min-w-full min-h-full flex items-center justify-center p-8">
          <div className="relative" style={{ width: MAP_WIDTH * ZOOM, height: MAP_HEIGHT * ZOOM }}>
            <div className="relative rounded-3xl shadow-[0_12px_28px_rgba(0,0,0,0.12)] origin-top-left overflow-hidden bg-[#E8F5E9]" style={{ width: MAP_WIDTH, height: MAP_HEIGHT, transform: `scale(${ZOOM})` }}>
              <div className="absolute bg-[#FDFBF7] pointer-events-none z-[1] border-x-[4px] border-dashed border-[#A38980]" style={{ left: PADDING + 15 * (CELL_SIZE + GAP), top: PADDING + 2 * (CELL_SIZE + GAP), width: 2 * CELL_SIZE + GAP, height: (GRID_HEIGHT - 4) * (CELL_SIZE + GAP) - GAP }} />
              {[8, 15, 22].map(y => (
                <div key={y} className="absolute bg-[#FDFBF7] pointer-events-none z-[1] border-y-[4px] border-dashed border-[#A38980]" style={{ left: PADDING + 2 * (CELL_SIZE + GAP), top: PADDING + y * (CELL_SIZE + GAP), width: (GRID_WIDTH - 4) * (CELL_SIZE + GAP) - GAP, height: CELL_SIZE }} />
              ))}
              <div className="absolute bg-white/50 border border-slate-300/60 pointer-events-none z-10 rounded-t-2xl" style={{ left: PADDING, top: PADDING, width: GRID_WIDTH * CELL_SIZE + (GRID_WIDTH - 1) * GAP, height: 2 * CELL_SIZE + GAP }} />
              <div className="absolute bg-white/50 border-l border-r border-slate-300/60 pointer-events-none z-10" style={{ left: PADDING, top: PADDING + 2 * (CELL_SIZE + GAP), width: 2 * CELL_SIZE + GAP, height: (GRID_HEIGHT - 4) * (CELL_SIZE + GAP) - GAP }} />
              <div className="absolute bg-white/50 border-l border-r border-slate-300/60 pointer-events-none z-10" style={{ left: PADDING + (GRID_WIDTH - 2) * (CELL_SIZE + GAP), top: PADDING + 2 * (CELL_SIZE + GAP), width: 2 * CELL_SIZE + GAP, height: (GRID_HEIGHT - 4) * (CELL_SIZE + GAP) - GAP }} />
              <div className="absolute bg-white/50 border border-slate-300/60 pointer-events-none z-10 rounded-bl-2xl" style={{ left: PADDING, top: PADDING + (GRID_HEIGHT - 2) * (CELL_SIZE + GAP), width: 14 * CELL_SIZE + 13 * GAP, height: 2 * CELL_SIZE + GAP }} />
              <div className="absolute bg-[#FDFBF7] border-t-2 border-b-2 border-amber-300/60 pointer-events-none z-10" style={{ left: PADDING + 14 * (CELL_SIZE + GAP), top: PADDING + (GRID_HEIGHT - 2) * (CELL_SIZE + GAP), width: 4 * CELL_SIZE + 3 * GAP, height: 2 * CELL_SIZE + GAP }} />
              <div className="absolute bg-white/50 border border-slate-300/60 pointer-events-none z-10 rounded-br-2xl" style={{ left: PADDING + 18 * (CELL_SIZE + GAP), top: PADDING + (GRID_HEIGHT - 2) * (CELL_SIZE + GAP), width: 14 * CELL_SIZE + 13 * GAP, height: 2 * CELL_SIZE + GAP }} />

              {placingState &&
                Array.from({ length: GRID_WIDTH * GRID_HEIGHT }).map((_, index) => {
                  const x = index % GRID_WIDTH;
                  const y = Math.floor(index / GRID_WIDTH);
                  if (x <= 1 || x >= GRID_WIDTH - 2 || y <= 1 || y >= GRID_HEIGHT - 2) return null;
                  return (
                    <div key={`${x}-${y}`} onClick={() => handleCellClick(x, y)} className="absolute rounded-md border border-pink-400/40 bg-white/20 hover:bg-pink-100/70 cursor-pointer z-20" style={{ left: PADDING + x * (CELL_SIZE + GAP), top: PADDING + y * (CELL_SIZE + GAP), width: CELL_SIZE, height: CELL_SIZE }} />
                  );
                })}

              {displayBuildings.map(building => (
                <div
                  key={building.id}
                  onPointerDown={() => {
                    if (placingState || building.id === 'gate') return;
                    wasLongPressed.current = false;
                    timerRef.current = window.setTimeout(() => {
                      wasLongPressed.current = true;
                      setPlacingState({
                        mode: 'move',
                        building: { id: building.id, name: building.name, width: building.width, height: building.height, color: building.color, description: building.description, facilityType: building.facilityType },
                        previewX: building.x,
                        previewY: building.y,
                        originalBuilding: building,
                      });
                      setEditingBuilding(null);
                    }, 180);
                  }}
                  onPointerUp={() => {
                    if (timerRef.current) {
                      window.clearTimeout(timerRef.current);
                      timerRef.current = null;
                    }
                  }}
                  onPointerLeave={() => {
                    if (timerRef.current) {
                      window.clearTimeout(timerRef.current);
                      timerRef.current = null;
                    }
                  }}
                  onClick={() => {
                    if (wasLongPressed.current || placingState) return;
                    setEditingBuilding(building);
                  }}
                  className={`absolute rounded-2xl shadow-xl flex items-center justify-center text-center font-bold ${building.color} border-4 ${building.id === 'gate' ? 'z-20' : 'z-10'}`}
                  style={{ left: PADDING + building.x * (CELL_SIZE + GAP), top: PADDING + building.y * (CELL_SIZE + GAP), width: building.width * CELL_SIZE + (building.width - 1) * GAP, height: building.height * CELL_SIZE + (building.height - 1) * GAP }}
                >
                  <span className="px-2 py-1 text-3xl font-black tracking-wide whitespace-nowrap" style={{ color: getBuildingTextColor(building) }}>
                    {building.name}
                  </span>
                </div>
              ))}

              {placingState?.previewX != null && placingState.previewY != null && (
                <div className={`absolute rounded-2xl flex items-center justify-center ${placingState.building.color} border-4 border-pink-500 opacity-85 z-40`} style={{ left: PADDING + placingState.previewX * (CELL_SIZE + GAP), top: PADDING + placingState.previewY * (CELL_SIZE + GAP), width: placingState.building.width * CELL_SIZE + (placingState.building.width - 1) * GAP, height: placingState.building.height * CELL_SIZE + (placingState.building.height - 1) * GAP }}>
                  <span className="text-3xl font-black" style={{ color: getBuildingTextColor(placingState.building.color) }}>
                    {placingState.building.name}
                  </span>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      <BottomSheetModal isOpen={showBuildModal} onClose={() => setShowBuildModal(false)} className="z-[96]">
        <div className="flex-1 overflow-y-auto hide-scrollbar pb-8 pt-8 px-5" {...buildScrollProps} ref={buildScrollProps.ref}>
          <h3 className="text-lg font-bold text-text-primary mb-4">新增建筑</h3>
          <div className="space-y-3">
            <input value={buildForm.name} onChange={event => setBuildForm(prev => ({ ...prev, name: event.target.value }))} placeholder="建筑名称" className="w-full h-10 rounded-xl px-3 border border-border-default" />
            <div className="flex gap-3">
              <label className="flex-1 text-xs font-bold text-text-secondary">宽度<input type="number" min={1} max={8} value={buildForm.width} onChange={event => setBuildForm(prev => ({ ...prev, width: Math.max(1, Math.min(8, Number(event.target.value) || 1)) }))} className="mt-1 w-full h-10 rounded-xl px-3 border border-border-default" /></label>
              <label className="flex-1 text-xs font-bold text-text-secondary">高度<input type="number" min={1} max={8} value={buildForm.height} onChange={event => setBuildForm(prev => ({ ...prev, height: Math.max(1, Math.min(8, Number(event.target.value) || 1)) }))} className="mt-1 w-full h-10 rounded-xl px-3 border border-border-default" /></label>
            </div>
            <textarea value={buildForm.description} onChange={event => setBuildForm(prev => ({ ...prev, description: event.target.value }))} placeholder="建筑描述" className="w-full rounded-xl px-3 py-2 border border-border-default min-h-[72px]" />
            <div className="grid grid-cols-1 gap-2">
              {BUILDING_COLOR_PALETTES.map(palette => (
                <button key={palette.id} type="button" onClick={() => setBuildForm(prev => ({ ...prev, color: palette.colorClass, facilityType: palette.category }))} className={`flex items-center gap-2 p-2.5 rounded-xl border-2 ${buildForm.color === palette.colorClass ? 'border-pink-500 bg-pink-50' : 'border-border-default'}`}>
                  <span className="w-6 h-6 rounded-lg border" style={{ backgroundColor: palette.bg, borderColor: palette.border }} />
                  <span className="text-xs font-bold">{palette.category}</span>
                </button>
              ))}
            </div>
            <button type="button" disabled={!buildForm.name.trim()} onClick={() => { setPlacingState({ mode: 'create', building: { ...buildForm, name: buildForm.name.trim() }, previewX: null, previewY: null }); setShowBuildModal(false); }} className="w-full py-3 rounded-xl accent-btn font-bold disabled:opacity-50">
              选择位置
            </button>
          </div>
        </div>
      </BottomSheetModal>

      <BottomSheetModal isOpen={Boolean(editingBuilding)} onClose={() => setEditingBuilding(null)} className="z-[96]">
        {editingBuilding && (
          <div className="flex-1 overflow-y-auto hide-scrollbar pb-8 pt-8 px-5" {...editScrollProps} ref={editScrollProps.ref}>
            <h3 className="text-lg font-bold text-text-primary mb-4 flex items-center gap-2"><Pencil className="w-4 h-4 text-pink-500" />编辑建筑</h3>
            <div className="space-y-3">
              <input value={editingBuilding.name} onChange={event => updateEditingBuilding({ name: event.target.value })} className="w-full h-10 rounded-xl px-3 border border-border-default" />
              <div className="flex gap-3">
                <label className="flex-1 text-xs font-bold text-text-secondary">宽度<input type="number" min={1} max={8} value={editingBuilding.width} onChange={event => updateEditingBuilding({ width: Math.max(1, Math.min(8, Number(event.target.value) || 1)) })} className="mt-1 w-full h-10 rounded-xl px-3 border border-border-default" /></label>
                <label className="flex-1 text-xs font-bold text-text-secondary">高度<input type="number" min={1} max={8} value={editingBuilding.height} onChange={event => updateEditingBuilding({ height: Math.max(1, Math.min(8, Number(event.target.value) || 1)) })} className="mt-1 w-full h-10 rounded-xl px-3 border border-border-default" /></label>
              </div>
              <textarea value={editingBuilding.description || ''} onChange={event => updateEditingBuilding({ description: event.target.value })} className="w-full rounded-xl px-3 py-2 border border-border-default min-h-[72px]" />
              <div className="grid grid-cols-1 gap-2">
                {BUILDING_COLOR_PALETTES.map(palette => (
                  <button key={palette.id} type="button" onClick={() => updateEditingBuilding({ color: palette.colorClass, facilityType: palette.category })} className={`flex items-center gap-2 p-2.5 rounded-xl border-2 ${editingBuilding.color === palette.colorClass ? 'border-pink-500 bg-pink-50' : 'border-border-default'}`}>
                    <span className="w-6 h-6 rounded-lg border" style={{ backgroundColor: palette.bg, borderColor: palette.border }} />
                    <span className="text-xs font-bold">{palette.category}</span>
                  </button>
                ))}
              </div>
              <div className="flex gap-2">
                <button type="button" onClick={() => { setPlacingState({ mode: 'move', building: { id: editingBuilding.id, name: editingBuilding.name, width: editingBuilding.width, height: editingBuilding.height, color: editingBuilding.color, description: editingBuilding.description, facilityType: editingBuilding.facilityType }, previewX: editingBuilding.x, previewY: editingBuilding.y, originalBuilding: editingBuilding }); setEditingBuilding(null); }} className="flex-1 py-3 rounded-xl bg-gray-100 font-bold flex items-center justify-center gap-1"><Move className="w-4 h-4" />改位置</button>
                <button type="button" onClick={() => { setDraft(prev => prev.filter(item => item.id !== editingBuilding.id)); setEditingBuilding(null); }} className="px-4 py-3 rounded-xl bg-red-50 text-red-500 font-bold"><Trash2 className="w-4 h-4" /></button>
              </div>
              <button type="button" onClick={() => setEditingBuilding(null)} className="w-full py-3 rounded-xl accent-btn font-bold">完成</button>
            </div>
          </div>
        )}
      </BottomSheetModal>
    </FullScreenModal>
  );
}
