import React, { useState } from 'react';
import { motion, useMotionValue, useTransform, PanInfo } from 'framer-motion';

interface SwipeableItemProps {
  children: React.ReactNode;
  onPin: () => void;
  onHide: () => void;
  isPinned: boolean;
  isUnhideMode?: boolean;
}

export const SwipeableItem: React.FC<SwipeableItemProps> = ({ children, onPin, onHide, isPinned, isUnhideMode }) => {
  const x = useMotionValue(0);
  const [isOpen, setIsOpen] = useState(false);
  const ACTIONS_WIDTH = isUnhideMode ? 70 : 140; // 70px per action
  const buttonOpacity = useTransform(x, [-30, 0], [1, 0]);

  const handleDragEnd = (e: any, info: PanInfo) => {
    const isSwipingLeft = info.offset.x < 0;
    const shouldOpen = isSwipingLeft && info.offset.x < -40;
    
    if (shouldOpen) {
      setIsOpen(true);
      x.set(-ACTIONS_WIDTH);
    } else {
      setIsOpen(false);
      x.set(0);
    }
  };

  const handleActionClick = (action: () => void) => {
    action();
    setIsOpen(false);
    x.set(0);
  };
  
  const handlePointerDownCapture = (e: React.PointerEvent) => {
    // We let framer motion handle it, but if we want to be safe about click prevention
  };

  return (
    <div className="relative overflow-hidden rounded-2xl w-full">
      <motion.div 
        className={`absolute inset-y-0 right-0 flex items-center justify-end z-0`} 
        style={{ width: ACTIONS_WIDTH, opacity: buttonOpacity }}
      >
        {!isUnhideMode && (
          <button 
            onClick={(e) => { e.stopPropagation(); handleActionClick(onPin); }}
            className="w-[70px] h-full bg-[#1e90ff] text-white flex items-center justify-center text-xs font-bold"
          >
            {isPinned ? '取消置顶' : '置顶'}
          </button>
        )}
        <button 
          onClick={(e) => { e.stopPropagation(); handleActionClick(onHide); }}
          className={`w-[70px] h-full bg-[#ff4757] text-white flex items-center justify-center text-xs font-bold rounded-r-2xl`}
        >
          {isUnhideMode ? '取消隐藏' : '隐藏'}
        </button>
      </motion.div>

      <motion.div
        style={{ x }}
        drag="x"
        dragDirectionLock
        dragConstraints={{ left: -ACTIONS_WIDTH, right: 0 }}
        dragElastic={0.1}
        onDragEnd={handleDragEnd}
        animate={{ x: isOpen ? -ACTIONS_WIDTH : 0 }}
        className="relative z-10 w-full"
        onClickCapture={(e) => {
          if (Math.abs(x.get()) > 5 && Math.abs(x.get()) !== ACTIONS_WIDTH) {
             e.stopPropagation();
          }
        }}
      >
        {children}
      </motion.div>
    </div>
  );
}
