import { CampusTrait, CampusType, CustomStartForm, getInstitutionLabel, getTraitLabel } from './constants';
import { resolveWorldRuleContent, WORLD_RULE_ENTRY_NAME } from './worldRuleModes';

const WORLD_NAME_CANDIDATES = ['圣樱学院', '圣樱学院v0.1'];
const ENTRY_NAME = 'user_玩家档案';

/** 世界书里只有这一条校园条目；任意校园类型/特征都覆盖它 */
export const SCHOOL_WORLDBOOK_ENTRY_NAME = 'school_圣樱中学';
export { WORLD_RULE_ENTRY_NAME };

let worldbookWriteQueue: Promise<void> = Promise.resolve();

function enqueueWorldbookWrite<T>(task: () => Promise<T>): Promise<T> {
  const run = worldbookWriteQueue.then(task, task);
  worldbookWriteQueue = run.then(
    () => undefined,
    () => undefined,
  );
  return run;
}

function normalizeEntryName(value: unknown): string {
  return String(value || '')
    .replace(/\u200b/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function sanitizeLine(value: string): string {
  return value.replace(/\r?\n/g, ' ').trim();
}

