export function formatCampusWorldbook(type: CampusType, trait: CampusTrait): string {
  const campus = getCampusMeta(type, trait);
  return [
    `<${campus.tag}>`,
    '学校概况:',
    `  名称: ${campus.name}`,
    `  性质: ${campus.nature}`,
    `  整体结构: ${campus.structure}`,
    `  核心道路: ${campus.road}`,
    '',
    '人员构成:',
    ...getPersonnelLines(type, trait),
    '',
    `  校园特性: ${getTraitLabel(type, trait)}`,
    `  场景标签: ${getInstitutionLabel(type)}`,
    `</${campus.tag}>`,
  ].join('\n');
}

function isBuiltinCampusType(type: string): type is CampusType {
  return type === '青春校园' || type === '玄幻修仙' || type === '魔法学院';
}

function isBuiltinCampusTrait(trait: string): trait is CampusTrait {
  return trait === '全男' || trait === '全女' || trait === '正常';
}

export function resolveCampusWorldbookContent(form: CustomStartForm): string {
  const worldview = String(form.worldview || '').trim();
  if (worldview) return worldview;

  const type = String(form.campusType || '青春校园');
  const trait = String(form.campusTrait || form.campusTraits?.[0] || '正常');
  if (isBuiltinCampusType(type) && isBuiltinCampusTrait(trait)) {
    return formatCampusWorldbook(type, trait);
  }
  return formatCampusWorldbook('青春校园', '正常');
}

function findSchoolWorldbookEntry(worldbook: WorldbookEntry[]): WorldbookEntry | undefined {
  const exact = worldbook.find(item => normalizeEntryName(item.name) === SCHOOL_WORLDBOOK_ENTRY_NAME);
  if (exact) return exact;

  const loose = worldbook.find(item => normalizeEntryName(item.name).includes(SCHOOL_WORLDBOOK_ENTRY_NAME));
  if (loose) return loose;

  return worldbook.find(item => String(item.content || '').includes(`<${SCHOOL_WORLDBOOK_ENTRY_NAME}>`));
}

function upsertNamedEntry(worldbook: WorldbookEntry[], entryName: string, content: string): void {
  const existing =
    worldbook.find(item => normalizeEntryName(item.name) === normalizeEntryName(entryName)) ||
    (entryName === SCHOOL_WORLDBOOK_ENTRY_NAME ? findSchoolWorldbookEntry(worldbook) : undefined);

  if (existing) {
    existing.name = entryName;
    existing.content = content;
    return;
  }

  worldbook.push({
    name: entryName,
    enabled: true,
    content,
  } as WorldbookEntry);
}

function isRoleArchiveEntry(name: string): boolean {
  return /^.+_.+_角色档案$/.test(name);
}

function applyPlayerArchive(worldbook: WorldbookEntry[], form: CustomStartForm): void {
  upsertNamedEntry(worldbook, ENTRY_NAME, formatPlayerArchive(form));
}

function applyCampusWorldbook(worldbook: WorldbookEntry[], form: CustomStartForm): void {
  upsertNamedEntry(worldbook, SCHOOL_WORLDBOOK_ENTRY_NAME, resolveCampusWorldbookContent(form));
}

function applyWorldRuleMode(worldbook: WorldbookEntry[], form: CustomStartForm): void {
  upsertNamedEntry(worldbook, WORLD_RULE_ENTRY_NAME, resolveWorldRuleContent(form.ruleEffectId));
}

function applyClassmateArchives(worldbook: WorldbookEntry[], form: CustomStartForm): void {
  const selected = new Set(form.selectedClassmateNames);
  const customByName = new Map(form.customClassmates.map(item => [item.name, item.content]));

  for (const entry of worldbook) {
    if (!isRoleArchiveEntry(entry.name)) continue;
    entry.enabled = selected.has(entry.name);
    if (form.classmateEdits[entry.name] !== undefined) {
      entry.content = form.classmateEdits[entry.name];
    }
  }

  for (const custom of form.customClassmates) {
    const existing = worldbook.find(item => item.name === custom.name);
    const content = form.classmateEdits[custom.name] ?? customByName.get(custom.name) ?? custom.content;
    if (existing) {
      existing.content = content;
      existing.enabled = selected.has(custom.name);
      continue;
    }
    worldbook.push({
      name: custom.name,
      enabled: selected.has(custom.name),
      content,
    } as WorldbookEntry);
  }
}

export function formatPlayerArchive(form: CustomStartForm): string {
  const identity = form.identityDescription.trim()
    ? `${sanitizeLine(form.identityName)}。${sanitizeLine(form.identityDescription)}`
    : sanitizeLine(form.identityName);

  return [
    '<role_user>',
    '玩家档案:',
    '  基本信息:',
    `    姓名: ${sanitizeLine(form.name)}`,
    `    年龄: ${sanitizeLine(form.age)}`,
    `    性别: ${form.gender}`,
    `    身份: ${identity}`,
    form.grade.trim() ? `    年级: ${sanitizeLine(form.grade)}` : '',
    form.startTime
      ? `    开局时间: ${form.startTime.year}年${form.startTime.month}月${form.startTime.day}日 ${String(form.startTime.hour).padStart(2, '0')}:${String(form.startTime.minute).padStart(2, '0')}`
      : '',
    form.startingLocation.trim() ? `    始发地: ${sanitizeLine(form.startingLocation)}` : '',
    `  外貌特征: ${sanitizeLine(form.appearance)}`,
    `  性格特征: ${sanitizeLine(form.personality)}`,
    '</role_user>',
  ]
    .filter(Boolean)
    .join('\n');
}

export function resolveSakuraWorldbookName(): string | null {
  try {
    const names = getWorldbookNames();
    for (const candidate of WORLD_NAME_CANDIDATES) {
      if (names.includes(candidate)) return candidate;
    }
    return names.find(name => name.includes('圣樱学院')) ?? null;
  } catch (error) {
    console.warn('[校园APP] 无法读取世界书列表:', error);
    return null;
  }
}

async function updateSakuraWorldbook(
  reason: string,
  updater: (worldbook: WorldbookEntry[]) => WorldbookEntry[],
): Promise<boolean> {
  const worldbookName = resolveSakuraWorldbookName();
  if (!worldbookName) {
    console.error(`[校园APP] 未找到圣樱学院世界书（${reason}）`);
    toastr.error('未找到名为「圣樱学院」的世界书', '入学失败');
    return false;
  }

  return enqueueWorldbookWrite(async () => {
    try {
      await updateWorldbookWith(
        worldbookName,
        worldbook => updater(worldbook),
        { render: 'immediate' },
      );
      console.info(`[校园APP] 已更新 ${worldbookName}（${reason}）`);
      return true;
    } catch (error) {
      console.error(`[校园APP] 更新世界书失败（${reason}）:`, error);
      toastr.error(`未能更新世界书：${reason}`, '入学失败');
      return false;
    }
  });
}

/** 入学时一次性写入玩家档案 + 校园特征 + 故事走向 + 同学集册，避免多次并发覆盖 */
export async function writeEnrollmentArchivesToWorldbook(form: CustomStartForm): Promise<boolean> {
  const ok = await updateSakuraWorldbook('入学档案写入', worldbook => {
    applyPlayerArchive(worldbook, form);
    applyCampusWorldbook(worldbook, form);
    applyWorldRuleMode(worldbook, form);
    applyClassmateArchives(worldbook, form);
    return worldbook;
  });

  if (ok) {
    console.info(`[校园APP] 已覆盖 ${SCHOOL_WORLDBOOK_ENTRY_NAME} 与 ${WORLD_RULE_ENTRY_NAME}`);
  }
  return ok;
}

export async function writeCampusWorldbookToWorldbook(form: CustomStartForm): Promise<void> {
  await updateSakuraWorldbook(`覆盖 ${SCHOOL_WORLDBOOK_ENTRY_NAME}`, worldbook => {
    applyCampusWorldbook(worldbook, form);
    return worldbook;
  });
}

export async function writePlayerArchiveToWorldbook(form: CustomStartForm): Promise<void> {
  await updateSakuraWorldbook(`写入 ${ENTRY_NAME}`, worldbook => {
    applyPlayerArchive(worldbook, form);
    return worldbook;
  });
}

export async function writeClassmateArchivesToWorldbook(form: CustomStartForm): Promise<void> {
  await updateSakuraWorldbook('同步同学集册', worldbook => {
    applyClassmateArchives(worldbook, form);
    return worldbook;
  });
}

export async function setWorldbookEntryEnabled(entryName: string, enabled: boolean): Promise<boolean> {
  const worldbookName = resolveSakuraWorldbookName();
  if (!worldbookName) {
    toastr.error('未找到名为「圣樱学院」的世界书', '工坊');
    return false;
  }
  return enqueueWorldbookWrite(async () => {
    try {
      let found = false;
      await updateWorldbookWith(
        worldbookName,
        worldbook => {
          const entry = worldbook.find(item => normalizeEntryName(item.name) === normalizeEntryName(entryName));
          if (entry) {
            entry.enabled = enabled;
            found = true;
          }
          return worldbook;
        },
        { render: 'immediate' },
      );
      return found;
    } catch (error) {
      console.error('[校园APP] 切换世界书条目失败:', error);
      toastr.error('未能同步世界书条目开关', '工坊');
      return false;
    }
  });
}

export async function upsertWorldbookArchives(
  entries: { name: string; content: string; enabled?: boolean }[],
): Promise<number> {
  const worldbookName = resolveSakuraWorldbookName();
  if (!worldbookName) {
    toastr.error('未找到名为「圣樱学院」的世界书', '工坊');
    return 0;
  }
  let written = 0;
  try {
    await updateWorldbookWith(worldbookName, worldbook => {
      for (const item of entries) {
        const name = String(item.name || '').trim();
        const content = String(item.content || '');
        if (!name || !content) continue;
        const existing = worldbook.find(entry => entry.name === name);
        if (existing) {
          existing.content = content;
          existing.enabled = item.enabled !== false;
        } else {
          worldbook.push({
            name,
            enabled: item.enabled !== false,
            content,
          } as WorldbookEntry);
        }
        written += 1;
      }
      return worldbook;
    });
    return written;
  } catch (error) {
    console.error('[校园APP] 写入工坊档案失败:', error);
    toastr.error('未能写入世界书档案', '工坊');
    return 0;
  }
}

export function isInitVarWorldbookEntry(name: string): boolean {
  return /\[?\s*initvar\s*\]?/i.test(name) && /变量初始化/.test(name);
}

function pickInitVarEntry(worldbook: WorldbookEntry[]): WorldbookEntry | undefined {
  return (
    worldbook.find(item => item.name === '[initvar]变量初始化勿开') ||
    worldbook.find(item => isInitVarWorldbookEntry(item.name)) ||
    worldbook.find(item => /\[?\s*initvar\s*\]?/i.test(item.name) || /变量初始化/.test(item.name))
  );
}

export async function getInitVarWorldbookContent(): Promise<string> {
  const worldbookName = resolveSakuraWorldbookName();
  if (!worldbookName) return '';
  try {
    const worldbook = await getWorldbook(worldbookName);
    return pickInitVarEntry(worldbook)?.content || '';
  } catch (error) {
    console.warn('[校园APP] 读取 initvar 失败:', error);
    return '';
  }
}

export async function writeInitVarCampusBuildings(content: string): Promise<boolean> {
  const worldbookName = resolveSakuraWorldbookName();
  if (!worldbookName) {
    console.warn('[校园APP] 未找到圣樱学院世界书，无法写入 initvar');
    return false;
  }

  return enqueueWorldbookWrite(async () => {
    try {
      let written = false;
      await updateWorldbookWith(
        worldbookName,
        worldbook => {
          const entry = pickInitVarEntry(worldbook);
          if (!entry) return worldbook;
          entry.content = content;
          written = true;
          return worldbook;
        },
        { render: 'immediate' },
      );
      if (written) {
        console.info(`[校园APP] 已更新 ${worldbookName} 的 initvar 校园建筑`);
      } else {
        console.warn('[校园APP] 未找到世界书条目「[initvar]变量初始化勿开」');
      }
      return written;
    } catch (error) {
      console.error('[校园APP] 写入 initvar 失败:', error);
      return false;
    }
  });
}

export async function deleteWorldbookEntries(entryNames: string[]): Promise<number> {
  const worldbookName = resolveSakuraWorldbookName();
  if (!worldbookName) {
    toastr.error('未找到名为「圣樱学院」的世界书', '工坊');
    return 0;
  }
  const names = new Set(entryNames.map(item => String(item || '').trim()).filter(Boolean));
  if (!names.size) return 0;
  let removed = 0;
  try {
    await updateWorldbookWith(worldbookName, worldbook => {
      const next = worldbook.filter(entry => {
        if (!names.has(entry.name)) return true;
        removed += 1;
        return false;
      });
      return next;
    });
    return removed;
  } catch (error) {
    console.error('[校园APP] 删除世界书条目失败:', error);
    toastr.error('未能删除世界书条目', '工坊');
    return 0;
  }
}
