export function resolveBuildingPalette(colorOrBuilding: string | CampusBuilding): BuildingColorOption | undefined {
  const colorStr = typeof colorOrBuilding === 'string' ? colorOrBuilding : (colorOrBuilding?.color || '');
  if (!colorStr) return undefined;

  const exact = BUILDING_COLOR_PALETTES.find(p => colorStr === p.colorClass || colorStr.includes(p.bg));
  if (exact) return exact;

  if (colorStr.includes('FFEDD4') || colorStr.includes('orange') || colorStr.includes('amber')) {
    return BUILDING_COLOR_PALETTES[0];
  }
  if (colorStr.includes('DBEAFE') || colorStr.includes('sky') || colorStr.includes('blue') || colorStr.includes('indigo')) {
    return BUILDING_COLOR_PALETTES[1];
  }
  if (colorStr.includes('FFE2E2') || colorStr.includes('red') || colorStr.includes('rose')) {
    return BUILDING_COLOR_PALETTES[2];
  }
  if (colorStr.includes('F3E8FF') || colorStr.includes('purple') || colorStr.includes('pink') || colorStr.includes('violet')) {
    return BUILDING_COLOR_PALETTES[3];
  }
  if (colorStr.includes('DBFCE7') || colorStr.includes('green') || colorStr.includes('emerald') || colorStr.includes('teal') || colorStr.includes('lime')) {
    return BUILDING_COLOR_PALETTES[4];
  }

  return undefined;
}

/** 日间 / 夜间建筑视觉样式（底色、描边、文字） */
export function getBuildingVisualStyle(
  colorOrBuilding: string | CampusBuilding,
  isDark = false,
): { backgroundColor: string; borderColor: string; textColor: string; colorClass: string } {
  const palette = resolveBuildingPalette(colorOrBuilding);
  if (palette) {
    return isDark
      ? {
          backgroundColor: palette.darkBg,
          borderColor: palette.darkBorder,
          textColor: palette.darkTextColor,
          colorClass: '',
        }
      : {
          backgroundColor: palette.bg,
          borderColor: palette.border,
          textColor: palette.textColor,
          colorClass: palette.colorClass,
        };
  }

  const colorStr = typeof colorOrBuilding === 'string' ? colorOrBuilding : (colorOrBuilding?.color || '');
  if (colorStr.includes('amber-700')) {
    return {
      backgroundColor: isDark ? '#3A2E14' : '#b45309',
      borderColor: isDark ? '#A67B42' : '#92400e',
      textColor: '#FFFFFF',
      colorClass: isDark ? '' : colorStr,
    };
  }

  // 未知颜色：夜间统一压暗，避免刺眼亮块
  return {
    backgroundColor: isDark ? '#243044' : '#e2e8f0',
    borderColor: isDark ? '#5B6B82' : '#94a3b8',
    textColor: isDark ? '#D1D9E6' : '#1e293b',
    colorClass: isDark ? '' : colorStr,
  };
}

export function getBuildingTextColor(colorOrBuilding: string | CampusBuilding, isDark = false): string {
  return getBuildingVisualStyle(colorOrBuilding, isDark).textColor;
}

