import { ChevronLeft, HelpCircle, Pencil } from 'lucide-react';
import { useEffect, useMemo, useRef, useState } from 'react';
import { ConfirmDialog } from '../状态栏/src/components/ui/ConfirmDialog';
import { useDraggableScroll } from '../状态栏/src/hooks/useDraggableScroll';
import { ensureMvuStatDataInitialized, getMvuStartTime, reloadMvuCampusBuildings, useCampusBuildings } from '../状态栏/src/hooks/useMvuData';
import {
  CUSTOM_GRADE_LABEL,
  CustomStartForm,
  GENDERS,
  GRADE_OPTIONS,
  Gender,
  INITIAL_CUSTOM_START_FORM,
  IdentityOption,
} from './constants';
import { CampusInfoSelector } from './CampusInfoSelector';
import { CampusMapPreview } from './CampusMapPreview';
import { IdentitySelector } from './IdentitySelector';
import { ActivitySelector } from './ActivitySelector';
import { ClassmateSelector } from './ClassmateSelector';
import { PhoneShell } from './PhoneShell';
import { TraitSelector } from './TraitSelector';
import { addCustomAppearance, addCustomPersonality, loadAppearances, loadPersonalities } from './traits';
import { getCampusTypeLabel } from './classmates';
import { getCustomCampusTraitLayout } from './campusCatalog';
import { buildInitVarFromLayout, campusLayoutToPreviewBuildings, getCampusLayoutBuildings, pickFallbackLocation } from './campusLayout';
import { formatCampusWorldbook, getInitVarWorldbookContent, writeInitVarCampusBuildings } from './playerArchive';
import { ArchiveEditPanel } from './ArchiveEditPanel';
const MODULES = ['校园信息', '个人信息', '同学集册', '校园活动', '始发地', '故事走向'] as const;

const RULE_EFFECT_OPTIONS = [
  {
    id: 'accepted',
    name: '平然校规模式',
    description: '学生会认为校规合理且正常',
  },
  {
    id: 'forced',
    name: '强制校规模式',
    description: '仅修改校规文本，不影响现实',
  },
] as const;

interface CustomStartScreenProps {
  onBack: () => void;
  onConfirm: (form: CustomStartForm) => void | Promise<void>;
}

function getTavernUserName(): string {
  const pick = (...values: unknown[]) => {
    for (const value of values) {
      const name = String(value || '').trim();
      if (name && name !== '{{user}}') return name;
    }
    return '';
  };
  try {
    const local = (window as any).SillyTavern;
    const parent = (window.parent as any)?.SillyTavern;
    return pick(local?.name1, parent?.name1, local?.getContext?.()?.name1, parent?.getContext?.()?.name1);
  } catch {
    return '';
  }
}

function createInitialForm(): CustomStartForm {
  const fallback = INITIAL_CUSTOM_START_FORM.startTime;
  return {
    ...INITIAL_CUSTOM_START_FORM,
    name: getTavernUserName(),
    gender: '男',
    grade: '高一',
    campusType: '青春校园',
    campusTrait: '全女',
    campusTraits: ['全女'],
    worldview: formatCampusWorldbook('青春校园', '全女'),
    appearanceId: INITIAL_CUSTOM_START_FORM.appearanceId,
    appearance: INITIAL_CUSTOM_START_FORM.appearance,
    personalityId: INITIAL_CUSTOM_START_FORM.personalityId,
    personality: INITIAL_CUSTOM_START_FORM.personality,
    startTime: getMvuStartTime(fallback),
  };
}

function SectionTitle({
  title,
  help,
  onHelp,
}: {
  title: string;
  help?: string;
  onHelp?: () => void;
}) {
  return (
    <div className="mb-3 flex items-center justify-between gap-2">
      <h3 className="text-sm font-bold text-text-primary">{title}</h3>
      {help ? (
        <button
          type="button"
          onClick={onHelp}
          className="w-7 h-7 rounded-full bg-gray-50 text-text-secondary flex items-center justify-center shrink-0"
          title="查看说明"
        >
          <HelpCircle className="w-4 h-4" />
        </button>
      ) : null}
    </div>
  );
}

function OptionChip({
  selected,
  label,
  onClick,
}: {
  selected: boolean;
  label: string;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`px-3.5 py-2 rounded-xl text-sm font-bold border transition-all ${
        selected
          ? 'accent-btn'
          : 'bg-white/70 text-text-secondary border-border-default hover:border-pink-200 hover:text-pink-500'
      }`}
    >
      {label}
    </button>
  );
}

export function CustomStartScreen({ onBack, onConfirm }: CustomStartScreenProps) {
  const [form, setForm] = useState<CustomStartForm>(() => createInitialForm());
  const [customGrade, setCustomGrade] = useState('');
  const [step, setStep] = useState(0);
  const [traitTick, setTraitTick] = useState(0);
  const [catalogTick, setCatalogTick] = useState(0);
  const [editingArchive, setEditingArchive] = useState(false);
  const [expandedRuleEffectId, setExpandedRuleEffectId] = useState<string | null>('accepted');
  const [layoutSyncing, setLayoutSyncing] = useState(false);
  const [confirming, setConfirming] = useState(false);
  const [helpTip, setHelpTip] = useState<{ title: string; message: string } | null>(null);
  const dragProps = useDraggableScroll<HTMLDivElement>();
  const layoutSyncPromiseRef = useRef<Promise<unknown>>(Promise.resolve());
  const layoutSyncTokenRef = useRef(0);
  const isFirst = step === 0;
  const isLast = step === MODULES.length - 1;
  const canConfirm = form.name.trim().length > 0 && form.startingLocation.trim().length > 0;
  const { names: buildingNames, loading: buildingsLoading } = useCampusBuildings();
  const buildings = useMemo(
    () =>
      buildingNames.map(name => ({
        id: name,
        name,
        x: 0,
        y: 0,
        width: 1,
        height: 1,
        color: '',
      })),
    [buildingNames],
  );

  const selectedTrait = form.campusTraits?.[0] || form.campusTrait || '全女';
  const layoutBuildings = useMemo(() => {
    const customLayout = getCustomCampusTraitLayout(String(form.campusType), String(selectedTrait));
    return customLayout || getCampusLayoutBuildings(String(form.campusType), String(selectedTrait));
  }, [form.campusType, selectedTrait, catalogTick]);
  const mapPreviewBuildings = useMemo(() => campusLayoutToPreviewBuildings(layoutBuildings), [layoutBuildings]);
  const appearances = useMemo(() => loadAppearances(form.gender), [form.gender, traitTick]);
  const personalities = useMemo(() => loadPersonalities(form.gender), [form.gender, traitTick]);
  const update = <K extends keyof CustomStartForm>(key: K, value: CustomStartForm[K]) => {
    setForm(prev => ({ ...prev, [key]: value }));
  };

  useEffect(() => {
    if (!buildings.length) return;
    if (form.startingLocation && buildings.some(item => item.name === form.startingLocation)) return;
    const fallback = pickFallbackLocation(layoutBuildings, form.startingLocation);
    setForm(prev => ({ ...prev, startingLocation: fallback || buildings[0].name }));
  }, [buildings, form.startingLocation, layoutBuildings]);

  useEffect(() => {
    let cancelled = false;
    const syncToken = ++layoutSyncTokenRef.current;
    setLayoutSyncing(true);
    const task = (async () => {
      const existing = await getInitVarWorldbookContent();
      const nextContent = buildInitVarFromLayout(layoutBuildings, existing);
      await writeInitVarCampusBuildings(nextContent);
      await reloadMvuCampusBuildings(layoutBuildings);
      if (cancelled || syncToken !== layoutSyncTokenRef.current) return;
      setForm(prev => {
        const nextLocation = pickFallbackLocation(layoutBuildings, prev.startingLocation);
        return nextLocation === prev.startingLocation ? prev : { ...prev, startingLocation: nextLocation };
      });
      setLayoutSyncing(false);
    })();
    layoutSyncPromiseRef.current = task.catch(error => {
      console.warn('[校园APP] 同步校园地图失败:', error);
      if (!cancelled && syncToken === layoutSyncTokenRef.current) setLayoutSyncing(false);
    });
    return () => {
      cancelled = true;
    };
  }, [form.campusType, selectedTrait, layoutBuildings]);

  const handleConfirmEnrollment = async () => {
    if (!canConfirm || confirming) return;
    setConfirming(true);
    try {
      // 等当前地图/initvar 写入完成，避免与 school_圣樱中学 并发覆盖
      await layoutSyncPromiseRef.current;
      await onConfirm(form);
    } finally {
      setConfirming(false);
    }
  };

  useEffect(() => {
    let cancelled = false;
    const fallback = INITIAL_CUSTOM_START_FORM.startTime;
    void (async () => {
      await ensureMvuStatDataInitialized();
      if (cancelled) return;
      const next = getMvuStartTime(fallback);
      setForm(prev => {
        const current = prev.startTime || fallback;
        if (
          current.year === next.year &&
          current.month === next.month &&
          current.day === next.day &&
          current.hour === next.hour &&
          current.minute === next.minute
        ) {
          return prev;
        }
        if (JSON.stringify(current) !== JSON.stringify(fallback)) return prev;
        return { ...prev, startTime: next };
      });
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const applyGender = (gender: Gender) => {
    const nextLooks = loadAppearances(gender);
    const nextMinds = loadPersonalities(gender);
    setForm(prev => ({
      ...prev,
      gender,
      appearanceId: nextLooks[0]?.id || '',
      appearance: nextLooks[0]?.description || '',
      personalityId: nextMinds[0]?.id || '',
      personality: nextMinds[0]?.description || '',
    }));
  };

  const goNext = () => setStep(prev => Math.min(prev + 1, MODULES.length - 1));
  const goPrev = () => setStep(prev => Math.max(prev - 1, 0));

  useEffect(() => {
    const resetScroll = () => {
      const scroller = dragProps.ref.current;
      if (!scroller) return;
      scroller.scrollTop = 0;
      scroller.scrollLeft = 0;
    };
    resetScroll();
    const frame = window.requestAnimationFrame(resetScroll);
    return () => window.cancelAnimationFrame(frame);
  }, [step, dragProps.ref]);

  return (
    <PhoneShell>
      <div className="relative w-full h-full flex flex-col overflow-hidden">
        <div className="sticky top-0 z-20 px-4 pt-2 pb-3 bg-white/55 backdrop-blur-md border-b border-white/70">
          <div className="flex items-center gap-3">
            <button
              type="button"
              onClick={() => (isFirst ? onBack() : goPrev())}
              className="w-8 h-8 rounded-full bg-white/80 border border-border-default flex items-center justify-center text-text-secondary hover:text-pink-500"
            >
              <ChevronLeft className="w-5 h-5" />
            </button>
            <div className="flex-1 min-w-0">
              <h2 className="text-lg font-bold text-text-primary">入学档案</h2>
              <p className="text-[11px] text-text-secondary mt-0.5">
                {MODULES[step]} · {step + 1}/{MODULES.length}
              </p>
            </div>
            <button
              type="button"
              onClick={() => setEditingArchive(true)}
              className="px-3 h-8 rounded-full bg-white/80 border border-border-default text-xs font-bold text-pink-500 flex items-center gap-1"
            >
              <Pencil className="w-3.5 h-3.5" />
              编辑
            </button>
          </div>
        </div>

        <div
          className="flex-1 overflow-y-auto overflow-x-hidden px-4 py-4 pb-28 hide-scrollbar"
          {...dragProps}
          ref={dragProps.ref}
        >
          {step === 0 && (
          <div className="space-y-4">
            <section className="glass rounded-3xl p-4 border border-white/80 shadow-sm">
              <h3 className="text-sm font-bold text-text-primary mb-3">校园信息</h3>
              <div className="space-y-4">
                <CampusInfoSelector
                  key={`campus-${catalogTick}`}
                  campusType={form.campusType}
                  campusTraits={form.campusTraits?.length ? form.campusTraits : form.campusTrait ? [form.campusTrait] : []}
                  onChange={(type, traits, worldview) => {
                    setCatalogTick(prev => prev + 1);
                    setForm(prev => ({
                      ...prev,
                      campusType: type as typeof prev.campusType,
                      campusTrait: (traits[0] || prev.campusTrait) as typeof prev.campusTrait,
                      campusTraits: traits,
                      worldview,
                    }));
                  }}
                />
              </div>
            </section>
            <section className="glass rounded-3xl p-4 border border-white/80 shadow-sm">
              <SectionTitle
                title="校园地图"
                help="可拖动查看完整布局。切换校园类型或特性后，会同步世界书 initvar 与 MVU 建筑。"
                onHelp={() =>
                  setHelpTip({
                    title: '校园地图说明',
                    message: '可拖动查看完整布局。切换校园类型或特性后，会同步世界书 initvar 与 MVU 建筑。',
                  })
                }
              />
              <CampusMapPreview buildings={mapPreviewBuildings} loading={layoutSyncing} showHint={false} />
            </section>
          </div>
          )}

          {step === 1 && (
          <section className="glass rounded-3xl p-4 border border-white/80 shadow-sm">
            <h3 className="text-sm font-bold text-text-primary mb-3">个人信息</h3>
            <div className="space-y-3">
              <label className="block">
                <span className="text-xs font-bold text-text-secondary mb-1.5 block">名称</span>
                <input
                  value={form.name}
                  onChange={e => update('name', e.target.value)}
                  placeholder="你的名字"
                  className="w-full h-10 rounded-xl px-3.5 bg-white/80 border border-border-default outline-none focus:ring-2 focus:ring-pink-200 focus:border-pink-300"
                />
              </label>
              <div>
                <p className="text-xs font-bold text-text-secondary mb-1.5">性别</p>
                <div className="flex flex-wrap gap-2">
                  {GENDERS.map(gender => (
                    <OptionChip
                      key={gender}
                      selected={form.gender === gender}
                      label={gender}
                      onClick={() => applyGender(gender as Gender)}
                    />
                  ))}
                </div>
              </div>
              <label className="block">
                <span className="text-xs font-bold text-text-secondary mb-1.5 block">年龄</span>
                <input
                  type="number"
                  min="1"
                  value={form.age}
                  onChange={e => update('age', e.target.value)}
                  className="w-full h-10 rounded-xl px-3.5 bg-white/80 border border-border-default outline-none focus:ring-2 focus:ring-pink-200 focus:border-pink-300"
                />
              </label>
              <div>
                  <p className="text-xs font-bold text-text-secondary mb-1.5">年级</p>
                  <div className="flex flex-wrap gap-2">
                    {GRADE_OPTIONS.map(grade => (
                      <OptionChip
                        key={grade}
                        selected={form.grade === grade}
                        label={grade}
                        onClick={() => update('grade', grade)}
                      />
                    ))}
                    <OptionChip
                      selected={!GRADE_OPTIONS.includes(form.grade as (typeof GRADE_OPTIONS)[number])}
                      label={CUSTOM_GRADE_LABEL}
                      onClick={() => update('grade', customGrade)}
                    />
                  </div>
                  {!GRADE_OPTIONS.includes(form.grade as (typeof GRADE_OPTIONS)[number]) && (
                    <input
                      value={customGrade}
                      onChange={e => {
                        setCustomGrade(e.target.value);
                        update('grade', e.target.value);
                      }}
                      placeholder="自定义年级或职务"
                      className="mt-2 w-full h-10 rounded-xl px-3.5 bg-white/80 border border-border-default outline-none focus:ring-2 focus:ring-pink-200 focus:border-pink-300"
                    />
                  )}
              </div>
              <div>
                <p className="text-xs font-bold text-text-secondary mb-1.5">相貌</p>
                <TraitSelector
                  title="相貌"
                  customLabel="自定义相貌"
                  namePlaceholder="如：清爽少年"
                  descriptionPlaceholder="描述外貌特征、发型、气质等"
                  gender={form.gender}
                  selectedId={form.appearanceId}
                  options={appearances}
                  onSelect={option => {
                    setForm(prev => ({
                      ...prev,
                      appearanceId: option.id,
                      appearance: option.description,
                    }));
                  }}
                  onCreate={(name, description) => {
                    const option = addCustomAppearance(form.gender, name, description);
                    setTraitTick(prev => prev + 1);
                    setForm(prev => ({
                      ...prev,
                      appearanceId: option.id,
                      appearance: option.description,
                    }));
                    return option;
                  }}
                />
              </div>
              <div>
                <p className="text-xs font-bold text-text-secondary mb-1.5">性格</p>
                <TraitSelector
                  title="性格"
                  customLabel="自定义性格"
                  namePlaceholder="如：热血直球"
                  descriptionPlaceholder="描述性格特点、处事方式和相处印象"
                  gender={form.gender}
                  selectedId={form.personalityId}
                  options={personalities}
                  onSelect={option => {
                    setForm(prev => ({
                      ...prev,
                      personalityId: option.id,
                      personality: option.description,
                    }));
                  }}
                  onCreate={(name, description) => {
                    const option = addCustomPersonality(form.gender, name, description);
                    setTraitTick(prev => prev + 1);
                    setForm(prev => ({
                      ...prev,
                      personalityId: option.id,
                      personality: option.description,
                    }));
                    return option;
                  }}
                />
              </div>
              <div>
                <p className="text-xs font-bold text-text-secondary mb-1.5">身份</p>
                <IdentitySelector
                  key={`identity-${catalogTick}`}
                  selectedId={form.identityId}
                  onSelect={(identity: IdentityOption) => {
                    setForm(prev => ({
                      ...prev,
                      identityId: identity.id,
                      identityName: identity.name,
                      identityDescription: identity.description,
                    }));
                  }}
                />
              </div>
            </div>
          </section>
          )}

          {step === 2 && (
          <section className="glass rounded-3xl p-4 border border-white/80 shadow-sm">
            <SectionTitle
              title="同学集册"
              help="显示全部角色档案，右上角标签为所属校园类型。选择非当前类型角色时会二次确认；被选中的角色档案会在入学时激活，其余角色档案将关闭。"
              onHelp={() =>
                setHelpTip({
                  title: '同学集册说明',
                  message:
                    '显示全部角色档案，右上角标签为所属校园类型。选择非当前类型角色时会二次确认；被选中的角色档案会在入学时激活，其余角色档案将关闭。',
                })
              }
            />
            <ClassmateSelector
              campusType={getCampusTypeLabel(String(form.campusType))}
              selectedNames={form.selectedClassmateNames || []}
              edits={form.classmateEdits || {}}
              customClassmates={form.customClassmates || []}
              onChange={({ selectedNames, edits, customClassmates }) => {
                setForm(prev => ({
                  ...prev,
                  selectedClassmateNames: selectedNames,
                  classmateEdits: edits,
                  customClassmates,
                }));
              }}
            />
          </section>
          )}

          {step === 3 && (
          <section className="glass rounded-3xl p-4 border border-white/80 shadow-sm">
            <SectionTitle
              title="校园活动"
              help="按月查看校园活动。粉色日期表示当月有活动，点选日期可调整开局时间。下方可勾选全部活动，默认都不勾选；勾选的活动会写入开篇提示词与建筑活动。"
              onHelp={() =>
                setHelpTip({
                  title: '校园活动说明',
                  message:
                    '按月查看校园活动。粉色日期表示当月有活动，点选日期可调整开局时间。下方可勾选全部活动，默认都不勾选；勾选的活动会写入开篇提示词与建筑活动。',
                })
              }
            />
            <ActivitySelector
              selectedIds={form.selectedActivityNames || []}
              edits={form.activityEdits || {}}
              startTime={form.startTime || INITIAL_CUSTOM_START_FORM.startTime}
              onChange={({ selectedIds, edits }) => {
                setForm(prev => ({
                  ...prev,
                  selectedActivityNames: selectedIds,
                  activityEdits: edits,
                }));
              }}
              onStartTimeChange={startTime => update('startTime', startTime)}
            />
          </section>
          )}

          {step === 4 && (
          <section className="glass rounded-3xl p-4 border border-white/80 shadow-sm">
            <SectionTitle
              title="始发地"
              help="从当前校园建筑中选择一个作为开局起点，确认入学后故事将从这里开始。"
              onHelp={() =>
                setHelpTip({
                  title: '始发地说明',
                  message: '从当前校园建筑中选择一个作为开局起点，确认入学后故事将从这里开始。',
                })
              }
            />
            {buildingsLoading && (
              <p className="text-xs text-text-secondary rounded-2xl border border-dashed border-border-default bg-white/60 p-3 mb-2">
                正在读取 / 初始化校园建筑数据…
              </p>
            )}
            {!buildingsLoading && !buildings.length && (
              <p className="text-xs text-text-secondary rounded-2xl border border-dashed border-border-default bg-white/60 p-3">
                当前聊天还没有可用的校园建筑数据。已尝试从世界书的 [initvar] 条目兜底初始化；若仍为空，请检查条目内容是否为合法 YAML/JSON，以及 MVU 脚本是否已启用。
              </p>
            )}
            <div className="space-y-2">
              {(mapPreviewBuildings.length ? mapPreviewBuildings : buildings).map(building => {
                const selected = form.startingLocation === building.name;
                return (
                  <button
                    key={building.id}
                    type="button"
                    onClick={() => update('startingLocation', building.name)}
                    className={`w-full text-left rounded-2xl border px-3.5 py-3 transition-all ${
                      selected
                        ? 'bg-pink-50 border-pink-300 shadow-sm'
                        : 'bg-white/70 border-border-default hover:border-pink-200'
                    }`}
                  >
                    <div className="flex items-center gap-2 min-w-0">
                      <span className={`w-4 h-4 rounded-full border flex items-center justify-center shrink-0 ${selected ? 'border-pink-500 bg-pink-500' : 'border-gray-300 bg-white'}`}>
                        {selected && <span className="w-1.5 h-1.5 rounded-full bg-white" />}
                      </span>
                      <span className={`text-sm font-bold truncate ${selected ? 'text-pink-700' : 'text-text-primary'}`}>
                        {building.name}
                      </span>
                    </div>
                  </button>
                );
              })}
            </div>
          </section>
          )}

          {isLast && (
          <section className="glass rounded-3xl p-4 border border-white/80 shadow-sm">
            <SectionTitle
              title="故事走向"
              help="确认入学后会覆盖世界书条目「world_世界观」。平然校规模式与强制校规模式对应两套不同世界观。"
              onHelp={() =>
                setHelpTip({
                  title: '故事走向说明',
                  message:
                    '确认入学后会覆盖世界书条目「world_世界观」。平然校规模式与强制校规模式对应两套不同世界观。',
                })
              }
            />
            <div>
              <p className="text-xs font-bold text-text-secondary mb-1.5">校规生效机制</p>
              <div className="space-y-2">
                {RULE_EFFECT_OPTIONS.map(option => {
                  const selected = form.ruleEffectId === option.id;
                  const expanded = expandedRuleEffectId === option.id;
                  return (
                    <button
                      key={option.id}
                      type="button"
                      onClick={() => {
                        update('ruleEffectId', option.id);
                        setExpandedRuleEffectId(option.id);
                      }}
                      className={`w-full text-left rounded-2xl border px-3.5 py-3 transition-all ${
                        selected
                          ? 'bg-pink-50 border-pink-300 shadow-sm'
                          : 'bg-white/70 border-border-default hover:border-pink-200'
                      }`}
                    >
                      <div className="flex items-center justify-between gap-2">
                        <div className="flex items-center gap-2 min-w-0">
                          <span className={`w-4 h-4 rounded-full border flex items-center justify-center shrink-0 ${selected ? 'border-pink-500 bg-pink-500' : 'border-gray-300 bg-white'}`}>
                            {selected && <span className="w-1.5 h-1.5 rounded-full bg-white" />}
                          </span>
                          <span className={`text-sm font-bold truncate ${selected ? 'text-pink-700' : 'text-text-primary'}`}>
                            {option.name}
                          </span>
                        </div>
                      </div>
                      {expanded && (
                        <p className="mt-2 text-xs leading-5 text-text-secondary pl-6">
                          {option.description}
                        </p>
                      )}
                    </button>
                  );
                })}
              </div>
            </div>
          </section>
          )}
        </div>

        <div className="absolute bottom-0 left-0 right-0 z-10 p-4 bg-gradient-to-t from-white via-white/95 to-transparent">
          {isFirst && (
            <button
              type="button"
              onClick={goNext}
              className="w-full py-3 rounded-2xl accent-btn text-base font-bold tracking-widest"
            >
              下一项
            </button>
          )}

          {!isFirst && !isLast && (
            <div className="grid grid-cols-2 gap-3">
              <button
                type="button"
                onClick={goPrev}
                className="w-full py-3 rounded-2xl text-text-secondary text-base font-bold bg-white border border-border-default shadow-sm"
              >
                上一项
              </button>
              <button
                type="button"
                onClick={goNext}
                className="w-full py-3 rounded-2xl accent-btn text-base font-bold"
              >
                下一项
              </button>
            </div>
          )}

          {isLast && (
            <div className="grid grid-cols-2 gap-3">
              <button
                type="button"
                onClick={goPrev}
                className="w-full py-3 rounded-2xl text-text-secondary text-base font-bold bg-white border border-border-default shadow-sm"
              >
                上一项
              </button>
              <button
                type="button"
                disabled={!canConfirm || confirming || layoutSyncing}
                onClick={() => void handleConfirmEnrollment()}
                className="w-full py-3 rounded-2xl accent-btn text-base font-bold tracking-widest disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {confirming ? '写入中…' : layoutSyncing ? '同步地图中…' : '确认入学'}
              </button>
            </div>
          )}
        </div>

        <ConfirmDialog
          open={Boolean(helpTip)}
          title={helpTip?.title || '说明'}
          message={helpTip?.message || ''}
          confirmText="我知道了"
          hideCancel
          onClose={() => setHelpTip(null)}
          onConfirm={() => setHelpTip(null)}
        />
        <ArchiveEditPanel
          open={editingArchive}
          form={form}
          onClose={() => setEditingArchive(false)}
          onFormChange={setForm}
          onCatalogChange={() => {
            setCatalogTick(prev => prev + 1);
            setTraitTick(prev => prev + 1);
          }}
        />
      </div>
    </PhoneShell>
  );
}
