import { CustomCampusTrait, loadCustomCampusTraitsByType, loadCustomCampusTypes, upsertCustomCampusTypes } from '../../../游戏开局/campusCatalog';
import { IdentityOption, TraitOption } from '../../../游戏开局/constants';
import { loadCustomIdentities, upsertCustomIdentities } from '../../../游戏开局/identities';
import { cloneNormalYouthCampusLayout, sanitizeCampusBuildingMap } from '../../../游戏开局/campusLayout';
import { loadCustomAppearances, loadCustomPersonalities, upsertCustomAppearances, upsertCustomPersonalities } from '../../../游戏开局/traits';
import { sanitizeFileName } from './workshopPack';

export const ENROLLMENT_PACK_KIND = 'campus-enrollment-workshop';
export const ENROLLMENT_PACK_VERSION = 2;

export interface EnrollmentCampusTypePack {
  id: string;
  name: string;
  traits: CustomCampusTrait[];
}

export interface EnrollmentPack {
  kind: typeof ENROLLMENT_PACK_KIND;
  version: number;
  name: string;
  exportedAt: string;
  campusTypes: EnrollmentCampusTypePack[];
  appearances: TraitOption[];
  personalities: TraitOption[];
  identities: IdentityOption[];
}

export type EnrollmentTab = 'campus' | 'looks' | 'minds' | 'identities';

export interface EnrollmentItem {
  id: string;
  label: string;
  extra?: string;
  content: string;
  traits?: CustomCampusTrait[];
}

function asList<T>(value: unknown): T[] {
  return Array.isArray(value) ? (value as T[]) : [];
}

function normalizePackTrait(trait: Partial<CustomCampusTrait> & { name?: string }): CustomCampusTrait | null {
  const name = String(trait?.name || '').trim();
  if (!name) return null;
  return {
    id: String(trait.id || '').trim() || `custom-trait-${name}`,
    name,
    worldview: String(trait.worldview || ''),
    mapLayout: sanitizeCampusBuildingMap(trait.mapLayout) || cloneNormalYouthCampusLayout(),
  };
}

function formatCampusContent(name: string, traits: CustomCampusTrait[]): string {
  if (!traits.length) return `${name}\n暂无校园特性`;
  return [
    name,
    ...traits.flatMap(trait => [
      '',
      `特性: ${trait.name}`,
      `地图建筑: ${Object.keys(trait.mapLayout || {}).length} 个`,
      trait.worldview?.trim() ? trait.worldview.trim() : '暂无世界观内容',
    ]),
  ].join('\n');
}

export function loadEnrollmentCatalog() {
  const traitsByType = loadCustomCampusTraitsByType();
  const campusTypes = loadCustomCampusTypes().map(item => {
    const traits = traitsByType[item.id] || [];
    return {
      id: item.id,
      label: item.name,
      extra: traits.length
        ? `${traits.map(trait => trait.name).join('、')} · 含地图`
        : '未设置特性',
      content: formatCampusContent(item.name, traits),
      traits,
      pack: { id: item.id, name: item.name, traits } satisfies EnrollmentCampusTypePack,
    };
  });
  const appearances = loadCustomAppearances().map(item => ({
    id: item.id,
    label: item.name,
    extra: item.gender,
    content: item.description || '暂无描述',
    pack: item,
  }));
  const personalities = loadCustomPersonalities().map(item => ({
    id: item.id,
    label: item.name,
    extra: item.gender,
    content: item.description || '暂无描述',
    pack: item,
  }));
  const identities = loadCustomIdentities().map(item => ({
    id: item.id,
    label: item.name,
    extra: '自定义身份',
    content: item.description || '暂无描述',
    pack: item,
  }));
  return { campusTypes, appearances, personalities, identities };
}

export function buildEnrollmentPack(
  name: string,
  selected: Record<EnrollmentTab, string[]>,
): EnrollmentPack {
  const catalog = loadEnrollmentCatalog();
  return {
    kind: ENROLLMENT_PACK_KIND,
    version: ENROLLMENT_PACK_VERSION,
    name: name.trim() || '入学档案工坊',
    exportedAt: new Date().toISOString(),
    campusTypes: catalog.campusTypes.filter(item => selected.campus.includes(item.id)).map(item => item.pack),
    appearances: catalog.appearances.filter(item => selected.looks.includes(item.id)).map(item => item.pack),
    personalities: catalog.personalities.filter(item => selected.minds.includes(item.id)).map(item => item.pack),
    identities: catalog.identities.filter(item => selected.identities.includes(item.id)).map(item => item.pack),
  };
}

export function parseEnrollmentPack(raw: unknown): EnrollmentPack {
  const data = raw && typeof raw === 'object' ? (raw as Record<string, unknown>) : {};
  const campusTypes = asList<EnrollmentCampusTypePack>(data.campusTypes)
    .concat(asList<EnrollmentCampusTypePack>(data.campus))
    .filter(item => item && (item.id || item.name))
    .map(item => ({
      id: String(item.id || item.name || '').trim(),
      name: String(item.name || '').trim(),
      traits: asList<CustomCampusTrait>(item.traits)
        .map(trait => normalizePackTrait(trait))
        .filter((trait): trait is CustomCampusTrait => Boolean(trait)),
    }))
    .filter(item => item.name);
  return {
    kind: ENROLLMENT_PACK_KIND,
    version: Number(data.version) || ENROLLMENT_PACK_VERSION,
    name: String(data.name || '').trim(),
    exportedAt: String(data.exportedAt || ''),
    campusTypes,
    appearances: asList<TraitOption>(data.appearances).filter(item => item && item.name),
    personalities: asList<TraitOption>(data.personalities).filter(item => item && item.name),
    identities: asList<IdentityOption>(data.identities).filter(item => item && item.name),
  };
}

export function isEnrollmentPack(raw: unknown): boolean {
  const data = raw && typeof raw === 'object' ? (raw as Record<string, unknown>) : {};
  if (data.kind === ENROLLMENT_PACK_KIND) return true;
  return Boolean(
    (Array.isArray(data.campusTypes) && data.campusTypes.length) ||
    (Array.isArray(data.appearances) && data.appearances.length) ||
    (Array.isArray(data.personalities) && data.personalities.length) ||
    (Array.isArray(data.identities) && data.identities.length),
  );
}

export function importEnrollmentPack(pack: EnrollmentPack) {
  const campus = upsertCustomCampusTypes(pack.campusTypes);
  const looks = upsertCustomAppearances(pack.appearances);
  const minds = upsertCustomPersonalities(pack.personalities);
  const identities = upsertCustomIdentities(pack.identities);
  return { campus, looks, minds, identities, total: campus + looks + minds + identities };
}

export function downloadEnrollmentPack(pack: EnrollmentPack, fileName: string) {
  const blob = new Blob([JSON.stringify(pack, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = `${sanitizeFileName(fileName || pack.name || '入学档案工坊')}.json`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}
