import { MvuTime } from '../hooks/useMvuData';
import { ForumPost, ForumReply } from '../types';

export type TagBlock = {
  attrs: Record<string, string>;
  inner: string;
};

function decodeAttr(value: string): string {
  return value
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .trim();
}

function parseAttrs(raw: string): Record<string, string> {
  const attrs: Record<string, string> = {};
  const re = /([^\s=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|(\S+)))?/g;
  let match: RegExpExecArray | null;
  while ((match = re.exec(raw))) {
    attrs[match[1]] = decodeAttr(match[2] ?? match[3] ?? match[4] ?? 'true');
  }
  return attrs;
}

export function extractBlocks(source: string, tag: string): TagBlock[] {
  const result: TagBlock[] = [];
  const re = new RegExp(`<${tag}(\\s[^>]*)?>([\\s\\S]*?)</${tag}>`, 'gi');
  let match: RegExpExecArray | null;
  while ((match = re.exec(source))) {
    result.push({
      attrs: parseAttrs(match[1] || ''),
      inner: String(match[2] || '').trim(),
    });
  }
  return result;
}

function extractForumXml(text: string): string[] {
  return extractBlocks(text, '论坛').map(block => block.inner);
}

export function getTagText(source: string, tag: string): string {
  const block = extractBlocks(source, tag)[0];
  return block?.inner.replace(/\s+/g, ' ').trim() || '';
}

function asNumber(value: unknown, fallback = 0): number {
  const num = Number(String(value ?? '').replace(/[^\d.-]/g, ''));
  return Number.isFinite(num) ? num : fallback;
}

function toGameTimestamp(year: number, month: number, day: number, hour = 0, minute = 0): number {
  return new Date(year, month - 1, day, hour, minute, 0, 0).getTime();
}

export function readMvuNumber(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string' && value.trim()) {
    const next = Number(value);
    return Number.isFinite(next) ? next : null;
  }
  if (Array.isArray(value) && value.length > 0) return readMvuNumber(value[0]);
  if (value && typeof value === 'object' && 'value' in (value as Record<string, unknown>)) {
    return readMvuNumber((value as Record<string, unknown>).value);
  }
  return null;
}

export function mvuTimeToTimestamp(time?: Partial<MvuTime> | null): number {
  const source = time && typeof time === 'object' ? (time as Record<string, unknown>) : null;
  const year = readMvuNumber(source?.年);
  const month = readMvuNumber(source?.月);
  const day = readMvuNumber(source?.日);
  const hour = readMvuNumber(source?.小时);
  const minute = readMvuNumber(source?.分钟);
  if (year == null || month == null || day == null) {
    return Date.now();
  }
  return toGameTimestamp(
    year,
    Math.min(12, Math.max(1, month)),
    Math.min(31, Math.max(1, day)),
    hour == null ? 0 : Math.min(23, Math.max(0, hour)),
    minute == null ? 0 : Math.min(59, Math.max(0, minute)),
  );
}

export function isTimestampInRange(nowTs: number, start: number, end: number): boolean {
  if (!Number.isFinite(nowTs) || !Number.isFinite(start) || !Number.isFinite(end)) return false;
  const from = Math.min(start, end);
  const to = Math.max(start, end);
  return nowTs >= from && nowTs <= to;
}

function normalizeForumTimestamp(timestamp: number, nowTs: number): number {
  if (!Number.isFinite(timestamp)) return nowTs;
  if (timestamp <= nowTs) return timestamp;
  const hour = 60 * 60 * 1000;
  const day = 24 * hour;
  if (timestamp - nowTs <= 2 * hour) return nowTs;
  if (timestamp - nowTs < day) return timestamp - day;
  const previousYear = new Date(timestamp);
  previousYear.setFullYear(previousYear.getFullYear() - 1);
  const wrapped = previousYear.getTime();
  return wrapped <= nowTs ? wrapped : nowTs;
}

export function formatForumRelativeTime(timestamp: number, nowTimestamp?: number): string {
  const nowTs = nowTimestamp || Date.now();
  if (!Number.isFinite(timestamp)) return '';
  const minutes = Math.round((nowTs - timestamp) / 60000);
  if (Math.abs(minutes) < 1) return '刚刚';
  if (minutes >= 1 && minutes < 60) return `${minutes}分钟前`;
  const hours = Math.floor(minutes / 60);
  if (hours >= 1 && hours < 24) return `${hours}小时前`;
  const days = Math.floor(hours / 24);
  if (days >= 1 && days < 30) return `${days}天前`;
  const date = new Date(timestamp);
  const month = date.getMonth() + 1;
  const day = date.getDate();
  const hour = String(date.getHours()).padStart(2, '0');
  const minute = String(date.getMinutes()).padStart(2, '0');
  return `${month}月${day}日 ${hour}:${minute}`;
}

export function parseForumClock(value: string, messageId = 0, now?: Partial<MvuTime> | null): number {
  const text = value.trim();
  const nowTs = mvuTimeToTimestamp(now);
  const year = Number(now?.年);
  const fallbackYear = Number.isFinite(year) ? year : new Date(nowTs).getFullYear();
  const emptyFallback = nowTs - Math.max(0, 10_000 - messageId) * 1000;
  if (!text) return normalizeForumTimestamp(emptyFallback, nowTs);

  const fullDateTime = text.match(/(\d{4})[-/.年]\s*(\d{1,2})[-/.月]\s*(\d{1,2})[日号]?[^\d]*(\d{1,2})[:：](\d{1,2})/);
  if (fullDateTime) {
    return normalizeForumTimestamp(
      toGameTimestamp(Number(fullDateTime[1]), Number(fullDateTime[2]), Number(fullDateTime[3]), Number(fullDateTime[4]), Number(fullDateTime[5])),
      nowTs,
    );
  }

  const fullDate = text.match(/(\d{4})[-/.年]\s*(\d{1,2})[-/.月]\s*(\d{1,2})/);
  if (fullDate) {
    return normalizeForumTimestamp(
      toGameTimestamp(Number(fullDate[1]), Number(fullDate[2]), Number(fullDate[3])),
      nowTs,
    );
  }

  const monthDayTime = text.match(/(\d{1,2})[-/.月]\s*(\d{1,2})[日号]?[^\d]*(\d{1,2})[:：](\d{1,2})/);
  if (monthDayTime) {
    return normalizeForumTimestamp(
      toGameTimestamp(fallbackYear, Number(monthDayTime[1]), Number(monthDayTime[2]), Number(monthDayTime[3]), Number(monthDayTime[4])),
      nowTs,
    );
  }

  const monthDay = text.match(/(\d{1,2})[-/.月]\s*(\d{1,2})/);
  if (monthDay) {
    const hour = Number(now?.小时);
    const minute = Number(now?.分钟);
    return normalizeForumTimestamp(
      toGameTimestamp(
        fallbackYear,
        Number(monthDay[1]),
        Number(monthDay[2]),
        Number.isFinite(hour) ? hour : 0,
        Number.isFinite(minute) ? minute : 0,
      ),
      nowTs,
    );
  }

  const clock = text.match(/(\d{1,2})[:：](\d{1,2})/);
  if (clock) {
    return normalizeForumTimestamp(
      toGameTimestamp(
        fallbackYear,
        Number(now?.月) || 1,
        Number(now?.日) || 1,
        Number(clock[1]),
        Number(clock[2]),
      ),
      nowTs,
    );
  }

  return normalizeForumTimestamp(emptyFallback, nowTs);
}

function parseReply(block: TagBlock, fallbackId: string, messageId: number, now?: Partial<MvuTime> | null): ForumReply | null {
  const content = getTagText(block.inner, '内容') || getTagText(block.inner, '正文') || block.inner.replace(/<楼中楼[\s\S]*?<\/楼中楼>/gi, '').replace(/<[^>]+>/g, '').trim();
  const authorName = block.attrs.作者 || getTagText(block.inner, '作者') || '匿名同学';
  if (!content && !authorName) return null;
  const nested = extractBlocks(block.inner, '楼中楼')
    .map((item, index) => parseReply(item, `${fallbackId}-n${index + 1}`, messageId, now))
    .filter((item): item is ForumReply => Boolean(item));
  return {
    id: block.attrs.id || fallbackId,
    authorName,
    authorAvatar: null,
    content,
    timestamp: parseForumClock(block.attrs.时间 || getTagText(block.inner, '时间'), messageId, now),
    likes: asNumber(block.attrs.点赞 ?? block.attrs.热度, 0),
    replies: nested,
  };
}

function parsePost(block: TagBlock, fallbackId: string, messageId: number, now?: Partial<MvuTime> | null): ForumPost | null {
  const title = getTagText(block.inner, '标题') || block.attrs.标题 || '';
  const content = getTagText(block.inner, '正文') || getTagText(block.inner, '内容') || '';
  if (!title && !content) return null;
  const replies = extractBlocks(block.inner, '回复')
    .map((item, index) => parseReply(item, `${block.attrs.id || fallbackId}-r${index + 1}`, messageId, now))
    .filter((item): item is ForumReply => Boolean(item));
  return {
    id: block.attrs.id || fallbackId,
    title: title || '无标题帖',
    content,
    authorName: block.attrs.作者 || getTagText(block.inner, '作者') || '匿名同学',
    authorAvatar: null,
    timestamp: parseForumClock(block.attrs.时间 || getTagText(block.inner, '时间'), messageId, now),
    likes: asNumber(block.attrs.热度 ?? block.attrs.点赞, 0),
    favorites: asNumber(block.attrs.收藏, 0),
    replies,
    board: block.attrs.板块 || getTagText(block.inner, '板块') || '校园闲聊',
  };
}

function mergeReplies(current: ForumReply[] = [], incoming: ForumReply[] = []): ForumReply[] {
  const map = new Map<string, ForumReply>();
  [...current, ...incoming].forEach(reply => {
    const prev = map.get(reply.id);
    if (!prev) {
      map.set(reply.id, reply);
      return;
    }
    map.set(reply.id, {
      ...prev,
      ...reply,
      replies: mergeReplies(prev.replies, reply.replies),
    });
  });
  return [...map.values()].sort((a, b) => a.timestamp - b.timestamp);
}

export function mergeForumPosts(current: ForumPost[], incoming: ForumPost[]): ForumPost[] {
  const map = new Map<string, ForumPost>();
  [...current, ...incoming].forEach(post => {
    const prev = map.get(post.id);
    if (!prev) {
      map.set(post.id, post);
      return;
    }
    map.set(post.id, {
      ...prev,
      ...post,
      replies: mergeReplies(prev.replies, post.replies),
    });
  });
  return [...map.values()].sort((a, b) => b.timestamp - a.timestamp);
}

export function parseForumPostsFromText(text: string, messageId = 0, now?: Partial<MvuTime> | null): ForumPost[] {
  const posts: ForumPost[] = [];
  extractForumXml(text).forEach((xml, blockIndex) => {
    extractBlocks(xml, '帖子').forEach((block, postIndex) => {
      const post = parsePost(block, `msg${messageId}-b${blockIndex + 1}-p${postIndex + 1}`, messageId, now);
      if (post) posts.push(post);
    });
  });
  return posts;
}

export function readAssistantMessages(): Array<{ message_id: number; message: string }> {
  const getters = [
    () => (typeof getChatMessages === 'function' ? getChatMessages('0-{{lastMessageId}}', { role: 'assistant' }) : []),
    () => {
      const parentGet = (window.parent as any)?.getChatMessages;
      return typeof parentGet === 'function' ? parentGet('0-{{lastMessageId}}', { role: 'assistant' }) : [];
    },
  ];
  for (const getter of getters) {
    try {
      const messages = getter();
      if (Array.isArray(messages) && messages.length) {
        return messages.map((item: any, index: number) => ({
          message_id: Number(item?.message_id ?? index),
          message: String(item?.message || ''),
        }));
      }
    } catch {
      // ignore
    }
  }
  return [];
}

export function loadForumPostsFromChat(now?: Partial<MvuTime> | null): ForumPost[] {
  const posts = readAssistantMessages().flatMap(item => parseForumPostsFromText(item.message, item.message_id, now));
  return mergeForumPosts([], posts);
}
