import { useEffect, useState } from 'react';
import { ChatThread } from '../types';
import { loadChatThreadsFromChat } from '../utils/chatParser';
import { useMvuSnapshot } from './useMvuData';

export function useChatThreads(): ChatThread[] {
  const mvuData = useMvuSnapshot();
  const [threads, setThreads] = useState<ChatThread[]>(() => loadChatThreadsFromChat(mvuData.时间));

  useEffect(() => {
    let cancelled = false;
    const sync = () => {
      const next = loadChatThreadsFromChat(mvuData.时间);
      if (cancelled) return;
      setThreads(prev => {
        if (!next.length && prev.length) return prev;
        return _.isEqual(prev, next) ? prev : next;
      });
    };

    sync();
    const timer = window.setInterval(sync, 800);
    try {
      eventOn(tavern_events.MESSAGE_RECEIVED, sync);
      eventOn(tavern_events.MESSAGE_UPDATED, sync);
      eventOn(tavern_events.CHAT_CHANGED, sync);
    } catch {
      // ignore
    }

    return () => {
      cancelled = true;
      window.clearInterval(timer);
    };
  }, [mvuData.时间]);

  return threads;
}
